(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-finance'] = AINOW['data/data-finance'] || {};
const financePrompts = [
  {"id":"fin-1","title":"3-Statement Model for SaaS Series A","prompt":"You are a CFO at a 3-year-old D2C skincare brand that hit $4.2M in revenue last year across DTC e-commerce (60%), Amazon (30%), and 3 retail partners (10%), with gross margins of 58% but burning $180K/month. The board is asking for a 3-year financial model ahead of a Series A raise. Build the complete model including: a revenue build by channel with growth assumptions grounded in cohort retention data, a COGS breakdown showing how gross margin evolves as you hit $10M and benefit from manufacturing scale, a headcount plan tied to revenue milestones, a monthly cash flow projection through 18 months, and three scenarios (base/bull/bear) with the key assumption driver for each. Include the top 5 KPIs the CFO would put on the weekly dashboard and the Excel formulas to calculate them.","tags":["financial-modeling","3-statement","saas","series-a"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"fin-2","title":"LBO Model — Mid-Market Manufacturing Buyout","prompt":"You are a VP at a lower-middle-market private equity firm evaluating the leveraged buyout of a $42M EBITDA industrial components manufacturer with $210M in revenue, 78% recurring revenue from long-term OEM contracts, and $18M in annual capex. The seller is asking 9x EBITDA. Structure a full LBO model: show the sources and uses table assuming 55% debt / 45% equity financing with a 6% blended cost of debt across a $185M senior secured term loan and a $45M mezzanine tranche, build a 5-year P&L with 3% annual revenue growth and $8M in year-1 cost synergies, project the debt paydown schedule and covenant compliance (total leverage ratio must stay below 5.5x), and calculate IRR and MOIC at exit multiples of 8x, 9x, and 10x EBITDA in year 5. Flag the two biggest risks to the debt service coverage ratio.","tags":["financial-modeling","lbo","private-equity","leveraged-buyout"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-3","title":"DCF Valuation — Profitable E-Commerce Brand","prompt":"You are a senior analyst at a boutique M&A advisory firm running a sell-side mandate for a profitable e-commerce outdoor gear brand with $28M in trailing revenue, 21% EBITDA margins, and five consecutive years of 30%+ growth. The owners want to understand their standalone intrinsic value before entertaining strategic offers. Build a 10-year DCF model: project free cash flow using a two-stage growth model (25% years 1–5, declining to 4% terminal), calculate WACC using a 5.2% risk-free rate, 5.8% equity risk premium, 1.1 relevered beta, and 40% debt weight at 6.5% pre-tax cost of debt. Show the enterprise value bridge from equity value, run a sensitivity table with WACC (8%–12%) on one axis and terminal growth rate (2%–5%) on the other, and explain in plain language why the terminal value represents 68% of total enterprise value and what that implies about investor risk.","tags":["financial-modeling","dcf","valuation","m&a"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-4","title":"Scenario Analysis — ClimateTech Revenue Model","prompt":"You are a Head of Finance at a Series B climate technology company selling carbon monitoring SaaS to mid-size industrials at $120K ACV with 115% net revenue retention, $8.2M ARR, and 18 months of runway at current burn of $620K/month. The CEO wants to present three credible scenarios to the board at next month's meeting covering the next 24 months. Build a scenario model in structured table format covering: (1) Base — 4 new enterprise logos per month at current ACV with 8% monthly churn reduction from a new CS program, (2) Bull — federal carbon reporting mandate accelerates pipeline by 6 months, doubling logo adds to 8/month, (3) Bear — enterprise procurement freezes extend sales cycles from 90 to 180 days, cutting new ARR adds by 40%. For each scenario show ending ARR, cumulative cash burn, months of runway remaining, and the Series C raise timing. Identify the single metric the CEO should track weekly as the leading indicator that distinguishes the bull from the bear case.","tags":["financial-modeling","scenario-analysis","saas","forecasting"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-5","title":"Merger Accretion/Dilution Model","prompt":"You are a corporate development director at a $2.4B market-cap regional bank (12x P/E, $200M net income) evaluating the acquisition of a $380M market-cap fintech payments processor (18x P/E, $21M net income) in an all-stock deal at a 25% premium. Build a merger accretion/dilution model: calculate shares issued, pro forma EPS, and whether the deal is accretive or dilutive in year 1 before synergies and after applying $8M in annual cost synergies (fully phased in year 2) and $4M in annual revenue synergies (phased in over 3 years). Show the breakeven synergy level required to reach zero dilution in year 1. Explain the goodwill and purchase price allocation mechanics, and flag the two accounting adjustments — deferred revenue haircut and acquired intangible amortization — that most commonly surprise acquirors in fintech deals.","tags":["financial-modeling","m&a","accretion-dilution","banking"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-6","title":"SaaS Unit Economics Model — Bottom-Up ARR Build","prompt":"You are a FP&A manager at a 60-person B2B SaaS company with $6.8M ARR growing 90% YoY, selling project management software to construction firms at three tiers: Starter ($4,800/year, 140 customers), Professional ($18,000/year, 62 customers), and Enterprise ($72,000/year, 11 customers). The VP Finance needs a bottom-up ARR model for the next 12 months. Build it with: monthly new logo adds by tier based on current pipeline coverage ratios (3.2x at Starter, 2.8x at Professional, 4.1x at Enterprise), gross and net churn assumptions by tier (Starter has 18% gross churn, Enterprise has 4%), expansion revenue from tier upgrades and seat additions modeled separately, a cohort waterfall showing ARR at the start and end of each month, and a customer acquisition cost payback period by tier. Conclude with a recommendation on which tier should receive the majority of next quarter's sales headcount investment.","tags":["financial-modeling","saas","unit-economics","arr"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-7","title":"Real Estate Development Pro Forma","prompt":"You are a real estate development analyst at a family office evaluating a ground-up 120-unit multifamily development in Nashville, TN. The land cost is $3.8M, hard construction costs are estimated at $148K per unit, soft costs (architecture, permits, financing fees) add another 18% on top of hard costs, and the project will take 26 months to complete. Target stabilized NOI is $2.1M at 95% occupancy with average rents of $1,850/month. Build a development pro forma covering: total project cost and construction draw schedule by quarter, construction loan sizing at 70% LTC at SOFR + 275bps, equity required and preferred return structure (8% pref, 70/30 waterfall above pref), a stabilization timeline with a 12-month lease-up absorption curve, exit cap rate sensitivity at 4.75%, 5.25%, and 5.75%, and development yield on cost versus market cap rate to assess whether the development spread justifies the execution risk.","tags":["financial-modeling","real-estate","development","pro-forma"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-8","title":"Working Capital Model — Seasonal Retail Business","prompt":"You are a finance director at a specialty outdoor retailer with $85M in annual revenue, highly seasonal cash flows (62% of revenue in Q3/Q4), and a $12M revolving credit facility currently drawn to $9M heading into January. COGS runs at 44%, with net 60 payment terms to suppliers and 45-day average inventory turns. Build a 13-week cash flow model covering January through March: show weekly operating cash inflows from collections (apply a 30-day DSO to December and January weekly revenue), outflows for inventory purchases (build March safety stock to 55 days), payroll ($640K biweekly), rent ($280K monthly), and debt service. Calculate the peak revolver draw week, the minimum liquidity cushion week, and the projected revolver balance at March 31. Flag whether the company needs to request a temporary overadvance and what covenant metrics (fixed charge coverage, total leverage) the bank will scrutinize most in Q1.","tags":["financial-modeling","working-capital","retail","cash-flow"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-9","title":"Restructuring Model — Distressed Manufacturer","prompt":"You are a restructuring advisor at a mid-size firm working with a $190M revenue industrial manufacturer that has $145M in term debt at 9.5%, $22M EBITDA, a 6.6x leverage ratio that breaches its 5.5x covenant, and only $4.2M in cash. The senior lender has engaged your firm to model restructuring options. Build a restructuring analysis comparing three paths: (1) out-of-court amendment and extend — the lender agrees to a 2-year maturity extension in exchange for a 50bps rate increase and $10M of equity cure, (2) debt-for-equity swap — convert $60M of term debt to equity at a negotiated enterprise value of $130M, reducing annual cash interest by $5.7M, (3) Chapter 11 pre-pack — 90-day process, $8M in professional fees, DIP financing at L+600, exit with a cleaner balance sheet at 3.5x leverage. Show the enterprise value, recovery rates to the senior lender, and residual equity value under each scenario. Identify which path maximizes total creditor recovery and why.","tags":["financial-modeling","restructuring","distressed","debt"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-10","title":"IPO Readiness Financial Model","prompt":"You are a VP of Finance at a vertical SaaS company serving dental practices with $41M ARR, 88% gross margins, 130% net revenue retention, and $3.1M in LTM EBITDA that recently turned positive for the first time. The CEO wants to assess IPO readiness for a potential offering 18–24 months from now. Build the financial narrative the S-1 will need to tell: project revenue for the next 8 quarters using cohort-based retention modeling and new logo growth, show the path to Rule of 40 compliance (currently at 94 on growth alone, but -7% on FCF margin), model the S&M efficiency ratio improvements required to reach 20% FCF margins by IPO, build a comparables table of 6 listed dental/healthcare SaaS peers showing EV/NTM Revenue multiples and the implied valuation range for your company at 10x, 12x, and 15x NTM revenue, and list the top 4 financial metrics the SEC and institutional investors will scrutinize most heavily in your S-1.","tags":["financial-modeling","ipo","saas","valuation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-11","title":"Zero-Based Budget — SaaS Company Entering Efficiency Era","prompt":"You are the FP&A director at a 200-person Series C SaaS company with $18M ARR growing 85% YoY but burning $2.1M/month, giving you 14 months of runway at current pace. The board has instructed management to cut burn to $1.2M/month without sacrificing ARR growth below 60%. Lead a zero-based budgeting exercise: categorize all $2.1M of monthly spend into four buckets — Revenue-Generating (direct sales, demand gen, CS), Revenue-Enabling (product, engineering), Overhead (G&A, legal, finance), and Discretionary — with current spend and headcount in each bucket. For each bucket propose cuts to reach the $900K reduction target, explain the 3–6 month revenue impact of each cut, identify which $400K of the cuts are reversible if ARR growth hits 80%+ in Q2, and build a monthly cash bridge from current burn to target burn showing the week-by-week implementation timeline. Include the top 3 risks to the plan and the tripwires that would trigger a secondary cost action.","tags":["fp&a","budgeting","zero-based","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"fin-12","title":"Rolling Forecast — Manufacturing Company","prompt":"You are an FP&A manager at a $320M revenue precision machining company with 14 plants across the US Midwest. The company uses SAP S/4HANA for ERP and Anaplan for planning. The current annual budget process takes 4 months and produces a plan that is outdated by February. The CFO wants to replace it with a 6-quarter rolling forecast updated monthly. Design the rolling forecast process from scratch: define the 12 driver-based inputs that will replace the 400-line P&L detail (include volume by product family, price realization, scrap rate, overtime %, and energy cost per unit), explain how to configure Anaplan to pull actuals from SAP automatically each month-end, set the governance calendar showing who submits assumptions by which day and who reviews before board submission, define the accuracy KPI (forecast vs. actual EBITDA at 13 weeks out, target within ±5%), and describe how to handle the transition from annual budget mentality to rolling forecast accountability at the plant controller level.","tags":["fp&a","forecasting","rolling-forecast","manufacturing"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-13","title":"Variance Analysis — Q3 Miss Explained to the Board","prompt":"You are the VP of FP&A at a $95M ARR enterprise software company. Q3 just closed with $23.1M in revenue versus a budget of $26.4M, and EBITDA of -$1.8M versus a budgeted -$0.4M. The board meeting is in 4 days and the CFO needs a full variance analysis written as a board-ready narrative. Structure the analysis as follows: start with a one-paragraph executive summary quantifying the $3.3M revenue miss and $1.4M EBITDA miss in plain language, then decompose the revenue miss into volume variance (fewer new logos than budgeted), price variance (higher than expected discounting in the federal vertical), and mix variance (Enterprise deals slipped to Q4, replaced by lower-ACV SMB deals), then explain the EBITDA miss by line item (which costs were over-budget and why), and close with a forward-looking section stating the Q4 pipeline coverage ratio, the three specific actions being taken to prevent recurrence, and a revised full-year guidance range with the key assumptions behind the range.","tags":["fp&a","variance-analysis","board-reporting","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-14","title":"FP&A Dashboard Design — Private Equity Portfolio Company","prompt":"You are the FP&A director at a PE-backed $160M revenue logistics company owned by a mid-market fund that requires a weekly operating dashboard sent every Monday at 8am. The current reporting is a static Excel file that takes the analyst 6 hours to compile. Design a best-in-class weekly operating dashboard: list the 15 metrics the PE sponsor will want to see organized into four sections (Revenue & Volume, Margin & Cost, Balance Sheet Hygiene, and People), specify the data source for each metric (TMS system, QuickBooks, Workday, Salesforce), write the DAX or SQL logic for the two hardest metrics to calculate (contribution margin by lane and driver utilization rate), explain how to automate the Monday delivery using Power BI Service scheduled refresh and email subscription, and identify the 3 metrics that have historically been the most predictive of quarterly EBITDA variance at logistics companies so the PE sponsor knows where to focus.","tags":["fp&a","dashboards","private-equity","logistics"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-15","title":"Annual Operating Plan — Consumer Brand Pre-Series B","prompt":"You are the Head of Finance at a 4-year-old premium pet food brand with $11.4M in trailing revenue split across DTC (45%), Chewy (35%), and 800 independent pet specialty stores (20%), gross margins of 52%, and 3 months of runway. You are raising a $6M Series B to fund the next 12 months. Build the Annual Operating Plan the investors will diligence: start with a revenue build by channel using realistic growth assumptions tied to specific marketing spend levels (paid social CAC of $38 for DTC, Chewy CPC bids, and a 60-store retail expansion plan with $8K average per-store sell-through), show COGS evolution as you shift 30% of production from a co-man at 62% COGS to your own micro-facility at 48% COGS by month 9, build the headcount plan with role-level detail for the 8 hires planned, produce a monthly P&L and cash flow through month 12, and show the Series B investor what ARR-equivalent LTV and payback period metrics look like for your subscription bundle customers.","tags":["fp&a","annual-plan","consumer-brand","fundraising"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-16","title":"Headcount Planning Model — Hypergrowth SaaS","prompt":"You are an FP&A senior analyst at a 380-person SaaS company growing 110% YoY with $34M ARR. The company is about to close a $50M Series C and needs to hire 140 people in the next 12 months across Sales (45 AEs and SDRs), Engineering (40 engineers), CS (25 CSMs), and G&A (30 roles). Build a headcount model that captures: monthly hiring plan by department with a 45-day average time-to-fill assumption, fully-loaded cost per hire by level (using Workday compensation bands and a 1.25x benefits/tax burden multiplier), ramp revenue contribution for each new AE (assume $0 in month 1-2, 50% quota attainment months 3-5, 100% from month 6), the impact of the 140 hires on the monthly burn rate and cash balance through month 18 post-close, and a sensitivity table showing how total cash burn changes if average time-to-fill slips from 45 to 60 or 75 days. Flag the three hiring bottlenecks most likely to cause the plan to miss.","tags":["fp&a","headcount","hiring","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-17","title":"SaaS Metrics Deep Dive — Cohort Analysis","prompt":"You are a VP of FP&A at a $22M ARR SaaS company whose last board meeting surfaced a concern about deteriorating cohort quality. New logo growth is strong at 8 logos/month, but NRR has slipped from 118% to 103% over 6 quarters. The board wants a cohort analysis presented at the next meeting in 3 weeks. Design the full cohort analysis: define the 4 cohort vintages to display (H1 2022, H2 2022, H1 2023, H2 2023), specify the revenue retention curve format (% of month-0 ARR retained at months 3, 6, 12, 18, 24), decompose NRR deterioration into its components — gross churn increase (which customer segments are churning more?), contraction expansion ratio (are upsells declining?), and logo mix shift (are newer cohorts smaller ACV?) — propose 3 product or CS interventions that address the root cause of the NRR compression, and show the board what NRR would need to recover to in order for the company to be Rule of 40 compliant at $35M ARR assuming a 45% growth rate.","tags":["fp&a","cohort-analysis","saas","nrr"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-18","title":"Cost Allocation Model — Multi-Product SaaS","prompt":"You are the controller at a 3-product SaaS company with $48M in total revenue across a core platform ($31M), an analytics add-on ($11M), and a mobile app ($6M), with a single shared engineering team of 85 people and a shared infrastructure cost of $3.2M annually on AWS. Finance needs to report segment gross margins for the first time ahead of a strategic review. Build a cost allocation methodology: define the allocation drivers for engineering headcount (use % of GitHub commits and Jira tickets by product as proxies), allocate AWS costs by product using CloudWatch cost explorer data segmented by service tag, allocate S&M costs using a first-touch attribution model from Salesforce opportunity source data, produce segment-level P&Ls showing gross margin and contribution margin for each product, and write a one-page memo explaining the methodology to the board audit committee including which allocation choices have the most material impact on reported segment margins and what a 10% shift in the engineering allocation assumption does to each product's gross margin.","tags":["fp&a","cost-allocation","segment-reporting","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-19","title":"KPI Framework — Marketplace Business","prompt":"You are the Head of Finance at a two-sided marketplace connecting freelance architects with residential renovation contractors, processing $28M in annual GMV with a 14% take rate generating $3.9M in net revenue. You are 6 months from a Series A and need to build an institutional-grade KPI framework. Define 20 metrics organized into 5 categories: Supply Health (architect supply, listing quality, supply NPS), Demand Health (contractor activation rate, repeat booking rate, demand NPS), Marketplace Liquidity (fill rate, time-to-match, cancellation rate), Unit Economics (CAC by side, LTV by side, contribution margin per transaction), and Financial Performance (GMV growth, net revenue growth, EBITDA). For each metric write the exact formula, the data source (Stripe, internal DB, Mixpanel), the current benchmark value, the Series A target value, and the single most important metric a Series A investor will ask about in the first 10 minutes of a diligence call and why.","tags":["fp&a","kpis","marketplace","series-a"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-20","title":"Pricing Model Sensitivity Analysis","prompt":"You are the Director of FP&A at a $14M ARR developer tools company currently charging $29/month per seat with 2,800 paying customers averaging 4.2 seats per account. The product team is proposing 3 pricing changes: (1) raise per-seat price to $39, (2) introduce a $199/month team tier with unlimited seats up to 15, (3) switch to usage-based pricing at $0.008 per API call with a $49/month minimum. Build a pricing sensitivity model: estimate price elasticity based on the 12% churn increase observed when a prior price increase was tested on a cohort of 200 accounts, model the ARR impact of each pricing scenario under optimistic (5% churn increase), base (12% churn increase), and pessimistic (22% churn increase) scenarios, calculate the net ARR impact at 12 months including both lost ARR from churn and gained ARR from price increase, and recommend which pricing scenario maximizes ARR at 12 months while keeping NRR above 100%, with the rationale grounded in the company's current customer mix between individual developers and teams.","tags":["fp&a","pricing","sensitivity-analysis","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-21","title":"M&A Target Screening Framework","prompt":"You are the head of corporate development at a $1.8B revenue enterprise cybersecurity company with $420M in cash, no debt, and a mandate from the board to deploy $200–400M in acquisitions over the next 18 months to accelerate entry into the identity governance market. Build a target screening framework: define 5 strategic fit criteria (adjacent product category, customer overlap below 40%, technology integration complexity, management retention likelihood, regulatory clean), define 5 financial fit criteria (minimum $20M ARR, 70%+ gross margins, NRR above 110%, sub-3x ARR acquisition price, no material off-balance-sheet liabilities), create a weighted scoring matrix with each criterion weighted by importance, apply the framework to evaluate three hypothetical acquisition types — a $35M ARR pure-play identity governance vendor, a $12M ARR adjacent PAM tool, and a $60M ARR overlapping network security vendor — and explain which deal type creates the most value given your current product gaps and the 18-month integration capacity constraint.","tags":["corporate-finance","m&a","corporate-development","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-22","title":"Capital Structure Optimization — Pre-IPO Tech Company","prompt":"You are the CFO of a pre-IPO cloud infrastructure company with $280M ARR, $62M EBITDA, $0 debt, and $190M of VC equity on the balance sheet at a $1.4B post-money valuation. You are 18 months from a planned IPO and the board wants to optimize the capital structure before going public. Analyze the optimal pre-IPO capital structure: evaluate the merits of taking on $150M in venture debt at SOFR+450 bps to extend runway and reduce dilution at IPO, compare this to a pre-IPO growth equity round at an estimated 12x forward revenue multiple, model the dilution impact of each option on founder and employee option pool ownership at various IPO valuations ($2B, $2.5B, $3B), calculate the WACC under current all-equity structure versus the leveraged structure assuming a 9.2% cost of equity and 7.8% pre-tax cost of debt at a 21% tax rate, and recommend the structure that balances IPO flexibility, dilution minimization, and financial covenant risk, with specific reference to how investment-grade tech issuers structure their pre-IPO balance sheets.","tags":["corporate-finance","capital-structure","ipo","wacc"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-23","title":"Dividend Policy Analysis — Mature Industrial Conglomerate","prompt":"You are the CFO of a $3.4B revenue diversified industrial conglomerate with $340M in EBITDA, $890M in net debt (2.6x leverage), $180M in annual free cash flow, and a history of paying a $1.40/share annual dividend ($110M total). The board is evaluating whether to maintain the dividend, cut it to fund a $400M bolt-on acquisition, or replace it with a $150M share buyback program. Analyze all three capital allocation options: model the pro forma leverage ratio under the acquisition scenario (assume the target is acquired for $400M at 8x EBITDA generating $50M EBITDA), calculate the dividend yield impact and likely stock price reaction to a dividend cut using comparables from industrial sector dividend cuts in 2020–2022, model the EPS accretion from the $150M buyback at the current $48/share stock price versus the acquisition's EPS accretion, assess which option best serves the two largest shareholder types (institutional income funds holding 38% and growth-oriented PE co-investors holding 22%), and write a one-paragraph board recommendation with the rationale.","tags":["corporate-finance","dividend-policy","capital-allocation","m&a"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-24","title":"Cross-Border M&A — Currency and Tax Structuring","prompt":"You are a senior director of corporate development at a US-listed software company ($4.2B market cap, 21% effective tax rate) evaluating the acquisition of a German B2B SaaS company with €42M ARR, €8M EBITDA, and a €280M asking price. The deal involves significant cross-border tax and currency complexity. Structure the deal to minimize tax leakage and FX risk: compare a US parent direct acquisition versus acquisition through a Netherlands holding company (using the Dutch participation exemption), estimate the withholding tax on dividend repatriation under each structure, model the purchase price in USD at spot rate (1.08 EUR/USD) versus hedged using 12-month forward contracts at 1.05, quantify the goodwill and deferred tax liability created under ASC 805, explain how the German IP should be valued and whether a post-acquisition IP migration to a low-tax jurisdiction is feasible within EU state aid rules, and flag the three most common deal-killers in German M&A that US acquirors encounter (works council consent, German foreign investment review, tax group unwinding).","tags":["corporate-finance","m&a","cross-border","tax-structuring"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-25","title":"WACC Deep Dive — Emerging Market Infrastructure","prompt":"You are a senior infrastructure finance analyst at a development finance institution evaluating a $340M toll road project in Colombia with a 30-year concession, peso-denominated revenues, and USD-denominated debt financing from a syndicate of international banks. Calculate the project WACC and equity IRR: use Colombia's sovereign spread of 210bps over US Treasuries, estimate the project beta by unlevering comparables from 4 listed Latin American infrastructure companies and relevering at the project's 65/35 debt/equity ratio, apply a 5.4% Colombian equity risk premium and a 3.8% country risk premium additive, model the equity returns in USD by applying a 20-year peso/dollar forward curve based on purchasing power parity, structure the debt at SOFR+285bps on the USD tranche and IBR+320bps on the local tranche, and calculate the all-in equity IRR at three traffic scenarios (P50, P75, P90) using the concession's traffic study. Identify the two assumptions with the widest confidence intervals and explain how a development finance institution would use a concessional first-loss tranche to attract commercial co-investors.","tags":["corporate-finance","wacc","infrastructure","emerging-markets"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-26","title":"Spin-Off Valuation — Conglomerate Breakup","prompt":"You are a strategy consultant advising the board of a $12B revenue industrial conglomerate whose sum-of-the-parts analysis suggests the market is applying a 25% conglomerate discount. The board is evaluating spinning off the $1.8B revenue specialty chemicals division (28% EBITDA margins, 12x EBITDA trading comps) from the $10.2B core industrial division (14% EBITDA margins, 8x EBITDA trading comps). Build the spin-off valuation and mechanics analysis: calculate the current blended trading multiple versus the pro forma sum-of-the-parts value, model the transaction costs including legal fees, bank fees, IT separation, and stranded overhead ($45M estimated), determine the optimal capital structure for each RemainCo and SpinCo (SpinCo can support 3.0x leverage, RemainCo is currently at 2.2x), analyze the tax-free spin requirements under Section 355, calculate the estimated value creation for shareholders under the spin versus a strategic sale of the chemicals division at 13x EBITDA, and recommend a transaction structure with a 24-month implementation roadmap.","tags":["corporate-finance","spinoff","valuation","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-27","title":"Equity Research — Initiating Coverage on a Cloud Security Stock","prompt":"You are an equity research analyst at a bulge bracket bank initiating coverage on a $4.8B market-cap cloud-native endpoint security vendor with $310M LTM revenue growing 38% YoY, 76% gross margins, -8% FCF margins improving toward breakeven, and a dominant NPS score of 68 in its core SMB and mid-market segments. Write a full initiation of coverage report: open with a 150-word investment thesis explaining the bull case in plain language, build a 3-year financial model with quarterly granularity for the next 6 quarters (show ARR, revenue, gross profit, EBITDA, and EPS), set a 12-month price target using a blended valuation methodology (60% weight on 12x NTM EV/Revenue, 40% weight on a DCF with 11% WACC and 4% terminal growth), identify the 3 key upside catalysts and 3 key downside risks with specific revenue impact quantified for each, compare the company to its 5 nearest listed peers on EV/NTM Revenue and EV/NTM Gross Profit, assign an Outperform rating, and write the risk disclosure section noting the speculative nature of pre-profitability growth stocks.","tags":["investment-analysis","equity-research","cloud-security","initiation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"fin-28","title":"Portfolio Construction — Endowment Investment Policy","prompt":"You are the CIO of a $280M university endowment with a 5% annual spending rate ($14M/year drawn to fund operations and scholarships), a 30-year investment horizon, and an existing portfolio that is 45% public equities, 22% fixed income, 18% private equity, 10% real assets, and 5% hedge funds. The investment committee is reviewing the IPS for the first time in 5 years given the rate environment and wants a modernized asset allocation. Build an updated Investment Policy Statement framework: propose a new strategic asset allocation that maintains the 5% spending rate while targeting 7.2% net real returns, justify the allocation shift from fixed income (reduce to 10%) into private credit (add 12% to capture 200bps yield premium over IG bonds), define the liquidity constraint (minimum 35% of portfolio must be in liquid assets redeemable within 90 days), establish manager selection criteria for each asset class including minimum AUM, track record length, and Sharpe ratio thresholds, set rebalancing triggers (5% absolute band around each target), and explain how the endowment's tax-exempt status allows it to invest in asset classes (MLPs, leveraged credit) that are suboptimal for taxable investors.","tags":["investment-analysis","portfolio","endowment","asset-allocation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-29","title":"Due Diligence Framework — Venture-Backed Series B","prompt":"You are a partner at a $400M growth equity fund conducting financial due diligence on a Series B investment in a $19M ARR vertical SaaS company serving independent insurance agencies, growing 72% YoY at a $1.4M monthly burn rate with 34 months of runway. You are considering leading a $25M round at a $95M pre-money valuation. Build a comprehensive due diligence framework covering 8 work streams: (1) Revenue Quality — validate ARR against Stripe and contracted billing schedules, check for multi-year prepays inflating reported ARR, (2) Cohort Analysis — request monthly cohort data going back to month 1 and calculate true gross and net dollar retention, (3) CAC and Payback — reconcile S&M spend to new logo adds by quarter, calculate blended and channel-specific CAC payback periods, (4) Churn Root Cause — interview 5 churned customers and 5 at-risk accounts to identify the top churn driver, (5) Management Quality — assess CFO's financial reporting hygiene and whether books are audit-ready, (6) Technology Moat — evaluate build vs. buy history and technical debt estimate, (7) Market Sizing — stress-test TAM of 40,000 independent agencies at $18K ACV, (8) Reference Checks — identify 3 back-channel references. For each work stream list 5 specific questions and the red flags that would kill the deal.","tags":["investment-analysis","due-diligence","venture","series-b"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-30","title":"Factor Investing — Quantitative Equity Strategy","prompt":"You are a quantitative analyst at a $1.2B long-only asset manager building a systematic factor equity strategy for a $150M institutional mandate benchmarked to the Russell 1000. The client wants exposure to Value, Quality, and Low Volatility factors with ESG screens that exclude tobacco, firearms, and companies in the bottom quintile of MSCI ESG ratings. Design the factor model: define the exact construction of each factor (Value = composite of P/E, P/B, and EV/EBITDA z-scores; Quality = composite of ROE, debt/equity, and earnings stability; Low Volatility = 12-month realized return standard deviation), specify the weighting methodology (equal factor weight with annual rebalancing, or risk-parity weighting), explain how to handle factor crowding risk when all three factors score highly for the same large-cap names, set maximum single-stock weight at 3% and maximum sector deviation from benchmark at ±10%, backtest the strategy concept using publicly available data from 2010–2023 and report expected information ratio and tracking error, and identify the market conditions (2020 growth rally, 2022 rate shock) where the strategy would have most significantly underperformed.","tags":["investment-analysis","factor-investing","quantitative","equity"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-31","title":"Personal Budget — Dual-Income Household with Student Debt","prompt":"You are a fee-only Certified Financial Planner working with a 32-year-old software engineer earning $148K gross in Austin, TX, and their 30-year-old partner earning $94K gross as a nurse, with a combined take-home pay of approximately $16,800/month after taxes, a $3,200/month mortgage (purchased at $485K with 10% down), $68K in student loans at 5.8% average interest, $22K in a combined emergency fund, $41K in 401(k)s, and a 6-month-old baby with no 529 account yet. Build a comprehensive household budget and financial plan: create a detailed monthly budget allocating take-home pay across housing (PITI), childcare ($2,200/month), food, transportation, insurance, debt service, and savings, calculate the optimal student loan payoff strategy comparing standard 10-year repayment versus aggressive 3-year payoff versus income-driven repayment, determine the correct order of financial priorities (high-interest debt vs. 401k match vs. 529 contributions vs. taxable investing), project net worth at age 42 and 52 under base and conservative scenarios, and identify the 3 biggest financial risks specific to this couple over the next 5 years.","tags":["personal-finance","budgeting","debt-payoff","financial-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-32","title":"Retirement Planning — Self-Employed Consultant at 48","prompt":"You are a CERTIFIED FINANCIAL PLANNER™ working with a 48-year-old independent management consultant earning $310K/year gross with highly variable income ($180K–$410K over the past 5 years), no employer retirement plan, $420K in a SEP-IRA, $85K in a taxable brokerage account (mostly S&P 500 index funds), a $1.4M primary residence with a $610K mortgage at 3.1%, no other debt, two kids (ages 14 and 11) with $95K combined in 529 accounts, and a retirement goal of maintaining $180K/year in real spending power at age 62. Build the retirement plan: calculate the maximum allowable SEP-IRA contribution in a year with $310K net self-employment income, evaluate whether converting to a solo 401(k) with Roth component makes sense given the income variability, project the SEP-IRA balance at 62 under 7% and 5% annual growth assumptions with aggressive contributions, calculate the Social Security benefit at 62 versus 67 versus 70 and the breakeven age for delaying, assess whether the primary residence should factor into the retirement plan (downsize vs. rental income), and design a tax-efficient drawdown sequence in retirement across the three account types.","tags":["personal-finance","retirement","self-employed","tax-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-33","title":"Debt Payoff Strategy — Medical Professional with Complex Liabilities","prompt":"You are a financial counselor working with a 34-year-old hospitalist physician earning $310K gross ($218K take-home after federal, state, and FICA taxes in California) with the following liabilities: $195K in federal student loans on PSLF track (8 years of qualifying payments completed, loans are at 6.0%), $28K in a car loan at 7.4%, $14,500 in credit card debt across 3 cards at APRs of 19.99%, 22.99%, and 15.99%, and a $580K mortgage at 4.25% with $495K remaining. Monthly fixed expenses are $8,400. Design a comprehensive debt payoff plan: calculate the mathematically optimal payoff sequence using both avalanche (highest APR first) and snowball (smallest balance first) methods and quantify the total interest saved by each approach, determine whether abandoning PSLF to aggressively pay down the student loans makes financial sense given the 8 years of payments already made, model the payoff timeline for all consumer debt under three monthly allocation scenarios ($1,500, $2,500, $4,000 to debt payoff), and identify the refinancing opportunities that are and are not appropriate given the PSLF track.","tags":["personal-finance","debt-payoff","student-loans","tax-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-34","title":"Tax Optimization — Stock Compensation for Tech Employee","prompt":"You are a CPA and financial planner working with a 38-year-old senior engineering manager at a publicly traded software company in Seattle (Washington state, no income tax) earning $195K base salary, with $280K in RSUs vesting over the next 4 years ($70K/year), $45K of NSOs with a $28 strike price (current stock price $91), a $620K brokerage account with $180K in embedded long-term capital gains, maxed-out 401(k), and an ESPP with a 15% discount and 24-month offering period. Build a multi-year tax optimization plan: calculate the federal tax owed on each RSU vest tranche under current income levels (including the FICA impact in the early vest years), design the optimal NSO exercise strategy comparing same-day sale versus multi-year exercise to spread income across brackets, determine whether harvesting $60K of the brokerage account gains to rebalance into international equity makes sense given the 0% LTCG rate threshold at this income level, explain how the ESPP should be treated as a sale versus a disqualifying disposition depending on holding period, and identify the three specific tax elections or strategies that could save the most in cumulative taxes over the 4-year vesting period.","tags":["personal-finance","tax-planning","equity-compensation","rsu"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-35","title":"First Home Purchase — Financial Readiness Analysis","prompt":"You are a financial planner working with a 29-year-old couple in Denver with combined gross income of $172K, $68K in savings earmarked for a down payment, $12K in an emergency fund, $45K in combined 401(k)s, no consumer debt, and a target purchase price of $620K for a 3-bedroom home. They want to know if they are truly ready to buy and how to optimize the purchase. Conduct a full financial readiness analysis: calculate the maximum mortgage they qualify for using the 28/36 debt-to-income rule, show the monthly payment breakdown at 10% versus 20% down payment at a current 30-year fixed rate of 7.1%, calculate the true all-in monthly cost of homeownership including mortgage, property tax (0.55% of assessed value), HOA ($320/month), insurance ($180/month), and a 1% annual maintenance reserve, determine whether PMI or a piggyback 80/10/10 loan structure saves more money if they buy at 10% down, show the 5-year and 10-year net cost of renting at $2,800/month versus buying including equity build-up and the opportunity cost of the down payment invested in the S&P 500 at 8% annual return, and give a clear buy/wait recommendation with specific financial milestones that would change the answer.","tags":["personal-finance","home-purchase","mortgage","budgeting"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-36","title":"Month-End Close — SaaS Company on NetSuite","prompt":"You are the Controller at a 180-person SaaS company with $24M ARR running NetSuite as the ERP and Stripe as the billing platform. The current month-end close takes 14 business days — the CFO wants it down to 5 days to support the planned IPO in 18 months. Design a best-in-class 5-day close process: map the current close to the 14-day timeline and identify the 3 bottlenecks causing the most delay (likely deferred revenue reconciliation, equity compensation expense, and multi-element arrangement allocation under ASC 606), design a day-by-day close calendar showing exactly which accounts must be reconciled on which day and which team member owns each task, write the NetSuite saved search query logic to automate the Stripe-to-deferred-revenue waterfall reconciliation, specify the key controls that must remain in place even as the close accelerates (3-way match on vendor invoices, CFO approval on journal entries over $25K, dual-control on wire payments), and describe the 4 technology integrations — Stripe to NetSuite via a middleware like Celigo, Carta for stock comp, Expensify for T&E, and Rippling for payroll — that will eliminate the most manual reconciliation steps.","tags":["accounting","month-end-close","netsuite","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"fin-37","title":"Revenue Recognition — Complex SaaS Arrangements Under ASC 606","prompt":"You are a senior technical accounting manager at a $65M ARR SaaS company that recently added implementation services and multi-year contracts with variable consideration to its product mix, creating significant ASC 606 complexity. The external auditor has flagged two transactions for technical accounting memos. Write the accounting analysis for both: Transaction 1 — a 3-year enterprise contract for $1.8M total comprising $1.2M of SaaS subscription, $400K of implementation services, and $200K of training, where the implementation services are determined to be highly interdependent with the subscription — analyze whether implementation and subscription are separate performance obligations, determine the standalone selling price for each using the adjusted market assessment approach, and compute the revenue recognition schedule. Transaction 2 — a $500K contract with a volume discount that triggers if the customer purchases $2M cumulatively over the 3-year term — analyze the variable consideration constraint under ASC 606-10-32-11, determine whether the most likely amount or expected value method applies, and calculate the transaction price recognized in year 1. For each transaction write the journal entries and balance sheet presentation.","tags":["accounting","asc-606","revenue-recognition","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-38","title":"Equity Compensation Accounting — Pre-IPO Stock Plan Under ASC 718","prompt":"You are the Technical Accounting Director at a pre-IPO SaaS company preparing for an IPO road show in 6 months. The company has 4 types of equity awards outstanding: (1) plain vanilla 4-year cliff vest ISOs granted at $2.80 FMV on January 1, 2022 to 120 employees, (2) performance-vesting RSUs that vest upon IPO if revenue exceeds $40M at the time of IPO, (3) secondary market RSU grants to executives where the FMV was set using a 409A valuation conducted 8 months ago, and (4) a CEO grant of 500,000 options with a market condition (vest only if 30-day VWAP exceeds 2x the IPO price within 3 years). Write the complete ASC 718 accounting analysis for each award type: determine the grant date fair value methodology (Black-Scholes for time-vesting options, Monte Carlo for market conditions, probability-weighted for performance conditions), calculate the expense recognition pattern and the cumulative catch-up entries required when IPO is deemed probable, explain the IPO-related accounting for the liquidity event, and identify the 3 disclosures the SEC's comment letter will most likely challenge in the S-1 registration statement.","tags":["accounting","asc-718","equity-compensation","ipo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-39","title":"Audit Preparation — First External Audit for a Series B Company","prompt":"You are the VP Finance at a Series B healthtech startup with $18M in annual revenue that has never had an external audit and needs audited financials in 90 days for a $30M Series B close. The books are in QuickBooks Online and the company has 3 finance staff including the controller. Design a 90-day audit readiness program: in the first 30 days focus on the highest-risk areas auditors will scrutinize most — revenue recognition under ASC 606 for a blend of recurring software subscriptions and professional services, completeness of deferred revenue (reconcile every contract in Salesforce to the deferred revenue balance), and related-party transactions (the CEO's spouse has a consulting contract); in the next 30 days prepare audit schedules for fixed assets (depreciation schedule, additions, disposals), equity (option activity, cap table reconciliation to Carta), and leases (ASC 842 ROU asset and lease liability calculation for the office lease); in the final 30 days conduct a pre-audit walkthrough with the team, resolve any open items, and prepare the PBC (provided by client) list. Include the 5 most common audit adjusting journal entries at companies of this size and maturity level.","tags":["accounting","audit","series-b","healthtech"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-40","title":"GAAP to Non-GAAP Reconciliation — Board Reporting","prompt":"You are the Controller at a $52M ARR SaaS company preparing the Q3 board package. The company reports both GAAP and Non-GAAP financials to the board and investor community. GAAP net loss for Q3 was -$4.2M. Management is proposing to adjust for stock-based compensation ($2.8M), amortization of acquired intangibles from the Flowbot acquisition ($420K), acquisition-related legal fees ($180K), a restructuring charge for the 12-person RIF in August ($340K), and depreciation acceleration on a data center lease exit ($95K). Write the complete GAAP to Non-GAAP reconciliation: for each adjustment state whether it meets the SEC's non-GAAP financial measures rules under Regulation G and Item 10(e) of Regulation S-K (particularly whether it is recurring or non-recurring in nature), calculate the Non-GAAP net loss and Non-GAAP EPS, write the standard boilerplate disclosure language explaining why management believes these Non-GAAP measures are useful to investors, flag which adjustments are most likely to attract SEC comment letter scrutiny, and explain the 2023 SEC enforcement action related to misleading non-GAAP adjustments that is most relevant to the restructuring charge inclusion.","tags":["accounting","non-gaap","sec-reporting","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-41","title":"Lease Accounting — ASC 842 Implementation for a Retailer","prompt":"You are the Controller at a 35-location specialty food retailer that has been on ASC 840 (operating leases kept off-balance-sheet) and must adopt ASC 842 for the fiscal year ending December 31. The company has 35 store leases (average remaining term 6.2 years, average monthly rent $18,400 with 2.5% annual escalators), 1 corporate office lease (remaining 4 years, $42K/month), and 3 equipment leases for refrigeration units (2-year terms, $8,200/month combined). Design the ASC 842 implementation: calculate the right-of-use asset and lease liability for the 3 largest store leases using the IBR of 6.8% (the company has no external debt, so IBR is estimated from the interpolated BBB- bond yield curve for the average lease term), explain how lease incentives and initial direct costs affect the opening ROU asset balance, show the income statement impact — under ASC 842 operating lease cost is straight-line (same as before) but the balance sheet now carries $48M+ of ROU assets and liabilities — and discuss the covenant implications with the company's bank (total debt covenant threshold is $35M), and provide the complete journal entries for adoption using the modified retrospective approach.","tags":["accounting","asc-842","lease-accounting","retail"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-42","title":"Impairment Testing — Goodwill and Intangibles Under ASC 350","prompt":"You are the Technical Accounting Manager at a $2.1B revenue technology company that acquired a digital marketing software company 2 years ago for $340M, generating $180M of goodwill and $95M of customer relationship intangibles (amortized over 8 years). The acquired business is now underperforming — Q3 revenue was $28M versus a budget of $41M due to a competitive pricing war, and management is preparing the Q3 10-Q. Conduct the goodwill impairment analysis under ASC 350: first determine whether qualitative triggering events require a Step 1 quantitative test (revenue miss, competitive environment deterioration, stock price decline of 22% since acquisition), perform the Step 1 impairment test by estimating the reporting unit's fair value using a DCF (discount rate of 13.5%, revised 5-year revenue forecast of $120M cumulative vs. the original $185M, 3% terminal growth) and a comparable company multiple approach (sector EV/Revenue multiple has compressed from 6x at acquisition to 3.8x), calculate the implied goodwill impairment charge, explain the financial statement presentation and the deferred tax effect, and draft the MD&A disclosure language that accurately describes the impairment without being excessively alarmist to investors.","tags":["accounting","impairment","goodwill","asc-350"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-43","title":"Seed Round Pitch Financials — EdTech Startup","prompt":"You are the co-founder and CEO of an EdTech startup building AI-powered study tools for community college students, pre-revenue, with 2,200 waitlist sign-ups, a team of 4, $80K in pre-seed funding, and a plan to raise a $1.5M seed round from angel investors and a micro-VC. Build the financial section of your seed pitch deck: create a 3-year financial projection showing a bottom-up revenue build from your go-to-market plan (target 50 community colleges in year 1 at $12K/year per institution, 150 in year 2, 400 in year 3), build the expense model showing how the $1.5M will be deployed across product development (40%), sales and marketing (30%), and operations (30%) over 18 months, calculate the key unit economics (CAC per institution using a direct outbound model at $8K per logo, LTV at 3-year average customer life, LTV:CAC ratio), build a 24-month cash flow projection with the fundraising events marked, show the valuation methodology you are using to set the $6M pre-money cap on your SAFE, and prepare 3 questions investors will definitely ask about your financial assumptions with honest, well-reasoned answers.","tags":["fundraising","seed-round","pitch-deck","edtech"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"fin-44","title":"Series A Data Room — Financial Due Diligence Package","prompt":"You are the CFO of a 3-year-old B2B SaaS company with $5.8M ARR growing 110% YoY, $820K monthly burn, 22 months of runway, and a term sheet for a $12M Series A from a top-10 institutional VC that requires a full financial due diligence data room within 3 weeks. Build the complete financial data room index and populate the key documents: the index should cover 8 sections — Historical Financials (3 years of P&Ls, balance sheets, and cash flow statements in GAAP format), ARR Detail (monthly MRR bridge since inception showing new, expansion, contraction, and churned MRR), Unit Economics (CAC by channel, LTV by cohort, payback period trends quarterly), Cap Table (fully diluted ownership including option pool, all warrants, and SAFEs on a pre and post-money basis), Option Pool (Carta report showing all grants, vesting schedules, and strike prices), Contracts (top 20 customer contracts, key renewal dates, and any unusual terms), Bank Records (6 months of statements), and Projections (18-month operating model). For each section describe the specific format, what makes it investor-grade versus audit-grade, and the 2 most common red flags VCs find in Series A data rooms that kill deals.","tags":["fundraising","series-a","due-diligence","data-room"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-45","title":"Cap Table Management — Series B and Option Pool Refresh","prompt":"You are the CFO of a Series B SaaS company that has just closed a $22M Series B led by a growth equity fund at a $88M pre-money valuation. Prior to the close, the cap table consisted of: Founders (2) owning 38% combined, Series A investors owning 28%, angel investors owning 9%, and an employee option pool of 15% (8% issued, 7% unissued), with a $2.8M convertible note outstanding at a $14M cap and 20% discount. Build the post-Series B cap table mechanics: convert the $2.8M note to equity (calculate shares issued at the cap versus the discount and apply the more favorable conversion for noteholders), calculate the Series B share issuance to achieve the $22M investment at the agreed price per share, determine whether a 5% option pool top-up (diluting all pre-money shareholders) was included in the pre or post-money valuation and show the impact on each shareholder class, calculate the post-close fully diluted ownership table, model the waterfall distribution at a hypothetical $130M acquisition (Series B 1x liquidation preference non-participating, Series A 1x non-participating), and identify the 3 most important cap table governance provisions that founders should negotiate before the next round.","tags":["fundraising","cap-table","series-b","equity"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-46","title":"VC Fund Metrics — Portfolio Performance Report","prompt":"You are a principal at a $120M early-stage venture fund (Fund III) that has deployed $78M across 24 portfolio companies over 4 years. 6 companies have had follow-on rounds marking up valuations, 2 have been written down to zero, 1 had a partial liquidity event (secondary sale returning $4.2M on a $2.1M investment), and the remaining 15 are marked at cost. LPs are asking for the Q3 performance report. Build the complete fund performance report: calculate the TVPI (Total Value to Paid-In), DPI (Distributions to Paid-In), RVPI (Residual Value to Paid-In), and IRR using the cash flow timeline of capital calls and distributions, build the portfolio company status table showing each investment, cost basis, current marked value, ownership %, and expected outcome category (likely write-off, hold, potential break-even, base case 3–5x, upside case 10x+), calculate the J-curve and show where Fund III sits relative to the vintage year median TVPI benchmark from Cambridge Associates, identify the 5 portfolio companies requiring the most active monitoring (based on runway and next fundraise timing), and write the 2-paragraph LP letter narrative that is honest about performance without triggering LP redemption requests.","tags":["fundraising","vc","fund-performance","investor-relations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-47","title":"Board Deck Financial Section — Quarterly Review","prompt":"You are the CFO of a $31M ARR SaaS company backed by two institutional VCs with board seats. The Q2 board meeting is in 2 weeks and you need to build the financial section of the board deck. Design an exemplary board financial section: the deck should have 8 slides covering (1) a one-page executive dashboard showing ARR, ARR growth YoY, Net New ARR vs. plan, NRR, gross margin, burn multiple, and months of runway all versus plan and prior quarter, (2) a revenue waterfall showing how Q2 ARR moved from opening to closing with new, expansion, contraction, and churn components labeled, (3) a P&L summary showing 3 quarters of actuals versus plan with key variances called out, (4) a cash flow bridge showing the Q2 operating burn, CapEx, and financing movements, (5) a unit economics update showing CAC payback trends, (6) a pipeline dashboard showing current quarter and next quarter pipeline coverage by stage, (7) an updated 12-month outlook with revised guidance range, (8) a forward-looking ask slide listing the 3 decisions that need board input this quarter. For each slide specify the exact data sources (Salesforce, NetSuite, Looker) and which metric the board will spend the most time debating.","tags":["fundraising","board-reporting","investor-relations","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-48","title":"SAFE Note Mechanics — Pre-Seed Financing","prompt":"You are a first-time founder raising your first $800K on a post-money SAFE with a $5M cap and no discount, using Y Combinator's standard post-money SAFE template. Three investors are participating: an angel writing $250K, an angel writing $150K, and a micro-VC writing $400K. Explain the complete mechanics of this financing: define exactly what the post-money SAFE cap means (the $5M is the post-money valuation inclusive of the SAFE principal itself), calculate each investor's pro-forma ownership percentage at the cap ($250K / $5M = 5.0%, etc.), explain how the SAFE converts at a Series A priced round — specifically what happens if the Series A pre-money valuation is $8M (above the cap, so SAFE converts at the cap price and investors get more shares per dollar than Series A investors) versus $3.5M (below the cap, SAFE converts at the Series A price), show the fully diluted cap table immediately after the SAFE close and after a hypothetical $4M Series A at $16M pre-money, explain the pro-rata rights provision and why the micro-VC will likely negotiate for it, and describe the 3 scenarios where SAFEs are disadvantageous to founders relative to priced rounds.","tags":["fundraising","safe","pre-seed","cap-table"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-49","title":"Investor Update — Monthly Letter to Seed Investors","prompt":"You are the CEO of a 14-month-old B2B SaaS company with $380K ARR that just had its best month ($48K new ARR) but also its most challenging (lost the second-largest customer at $72K ARR, reducing NRR to 88%, and extended the runway forecast from 10 months to 9 months after missing a $200K enterprise deal). Write an exemplary monthly investor update: open with a one-paragraph honest summary that does not bury the churn news, present the 5 key metrics in a clean table (MRR, ARR, MoM growth, NRR, runway), give a clear account of the $72K churn — what happened, what you learned, and what you changed in the qualification process, report the $48K new ARR add by deal and explain why the enterprise miss happened and what the updated probability of closing is in Q4, state the 3 things you need from investors this month (two warm intros to specific companies, one legal reference), and close with the 3 metrics you will report next month that will tell investors whether the business is improving. Keep the update under 600 words and make it a model of transparency without being alarmist.","tags":["fundraising","investor-relations","investor-update","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-50","title":"Financial Risk Identification — Enterprise SaaS Company","prompt":"You are the VP of Finance and Risk at a $78M ARR enterprise SaaS company selling to Fortune 500 clients with average contract values of $380K. The company has high customer concentration (top 5 customers represent 44% of ARR), 87% of revenue is subscription, 13% is professional services, and the company carries $45M in term debt at SOFR+375bps with financial covenants (total leverage below 4.5x, minimum ARR growth of 20% YoY). Conduct a comprehensive enterprise financial risk assessment across 5 categories: (1) Customer Concentration Risk — identify the specific scenarios (non-renewal of top 2 customers) that would breach the ARR growth covenant and model the resulting covenant cure options, (2) Interest Rate Risk — model the cash interest impact if SOFR moves from 5.3% to 7% on the $45M floating-rate debt, (3) Revenue Quality Risk — assess the durability of the 13% professional services revenue and its gross margin drag (18% PS margin versus 82% subscription margin), (4) FX Risk — quantify the exposure from $12M of ARR denominated in EUR and GBP with invoicing in USD, (5) Operational Risk — identify the top 3 single points of failure in the finance function (key person dependencies, systems, controls). For each risk category assign a likelihood/impact rating and propose a specific mitigation action.","tags":["risk-management","enterprise","saas","financial-risk"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-51","title":"FX Hedging Program — Mid-Size Exporter","prompt":"You are the Treasurer at a $240M revenue US-based industrial equipment manufacturer that exports 35% of revenue to Europe (invoiced in EUR) and 18% to Japan (invoiced in JPY), with a functional currency of USD. The CFO has asked you to design a formal FX hedging program after a 14% EUR/USD depreciation last quarter cost the company $6.2M in realized FX losses. Design the hedging program from scratch: define the hedging objective (protect 80% of forecasted foreign currency cash flows over a rolling 12-month horizon), select the appropriate hedging instruments comparing plain vanilla forward contracts, purchased EUR put options (cost ~1.8% of notional), and zero-cost collars (floor at 1.02 EUR/USD, cap at 1.14), explain the ASC 815 cash flow hedge accounting requirements including the effectiveness testing methodology, calculate the notional hedging amounts for the next 4 quarters based on a $84M EUR revenue forecast and a $43M JPY revenue forecast, build a hedge effectiveness scorecard showing how to measure and report hedge performance quarterly, and write the Treasury Policy section on FX risk that would satisfy the CFO and external auditors.","tags":["risk-management","fx-hedging","treasury","derivatives"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-52","title":"Interest Rate Risk — Bank ALCO Stress Test","prompt":"You are the Chief Risk Officer at a $1.8B community bank with a traditional loan portfolio ($1.1B in commercial real estate, $280M in C&I, $190M in residential mortgages) funded by core deposits (68%) and FHLB borrowings (32%). The Fed has raised rates 525bps in 18 months and the ALCO is concerned about net interest margin compression and unrealized bond losses. Conduct a comprehensive interest rate risk analysis: model the NII (net interest income) impact of three rate scenarios — base (rates unchanged), +200bps parallel shift, and -100bps parallel shift — using a standard repricing gap analysis that separates assets and liabilities into maturity buckets (0–3 months, 3–12 months, 1–3 years, 3–5 years, 5+ years), calculate the economic value of equity (EVE) sensitivity under each scenario, quantify the AOCI impact from the available-for-sale bond portfolio (currently $320M of Agency MBS with an average duration of 5.4 years) under the +200bps scenario, assess whether the bank needs to add receive-fixed interest rate swaps to reduce asset sensitivity, and write the ALCO memo recommending specific balance sheet actions with the NII impact of each action quantified.","tags":["risk-management","interest-rate-risk","banking","alco"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-53","title":"Credit Risk Framework — B2B SaaS Accounts Receivable","prompt":"You are the Director of Finance at a $55M ARR enterprise SaaS company that extended net 60 payment terms to enterprise customers and now has $9.2M in accounts receivable with $1.8M more than 90 days past due, including $420K from a customer that filed Chapter 11 last week. Build a credit risk management framework: first triage the current AR aging and calculate the required bad debt reserve under ASC 450 using a historical loss rate method (apply your 2.1% historical write-off rate) and compare to the CECL expected credit loss method under ASC 326 which requires forward-looking adjustments, draft the accounting entry to record the $420K reserve for the bankrupt customer and the disclosure language for the footnotes, design a prospective credit policy that sets credit limits based on Dun & Bradstreet scores and revenue size, defines the approval matrix for contract terms beyond net 30, and establishes an automated 15/30/45/60 day dunning sequence in Salesforce, and calculate the cash flow impact of reducing DSO from the current 62 days to a target of 42 days assuming $55M ARR running ratably at $4.6M/month revenue.","tags":["risk-management","credit-risk","accounts-receivable","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-54","title":"Liquidity Risk — Stress Test for a Growth-Stage Company","prompt":"You are the CFO of a Series C logistics technology company with $8.4M in cash, a $5M revolving credit facility (currently undrawn, borrowing base tied to eligible accounts receivable of $3.2M), $2.1M monthly operating burn, and $18M in ARR. The board has asked for a formal liquidity stress test after two portfolio companies in the same VC's fund ran out of cash without warning. Build a 6-scenario liquidity stress test: define 6 scenarios ranging from mild (revenue growth slows from 80% to 40% YoY) to severe (top customer ($2.4M ARR) churns in month 2 AND the revolver lender freezes the facility due to borrowing base deficiency), for each scenario project the monthly cash balance through 12 months, calculate the exact month cash falls below $2M (the operating minimum) and the zero-cash date, identify the specific financing levers available in each scenario (cost cuts, AR factoring at 85% advance rate, emergency equity raise, bridge note from existing investors), rank the scenarios by probability and impact, and write the liquidity risk policy statement including the minimum cash balance covenant the company should maintain and the tripwires that trigger the board liquidity protocol.","tags":["risk-management","liquidity","stress-testing","startup"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-55","title":"Commodity Price Risk — Food Manufacturing Hedging Strategy","prompt":"You are the VP of Finance and Treasury at a $180M revenue specialty food manufacturer whose top 3 raw material inputs are durum wheat (28% of COGS), olive oil (19% of COGS), and corrugated packaging (11% of COGS). Commodity price volatility caused a 320bps gross margin swing last fiscal year — wheat prices rose 28% and olive oil rose 41% due to supply shocks. Design a commodity risk management program: calculate the annual notional exposure for each commodity based on current purchase volumes and spot prices (durum wheat 22,000 metric tons at $385/MT, olive oil 8,400 metric tons at $4,200/MT, corrugated packaging tied to OCC index at $145/ton for 14,000 tons), evaluate the hedging instruments available for each commodity (CBOT wheat futures contracts for wheat, OTC fixed-price forward contracts for olive oil since no liquid futures exist, and supplier price caps for packaging), design an 18-month hedge book covering 70% of wheat exposure and 50% of olive oil exposure, calculate the estimated reduction in gross margin volatility, explain how to account for the wheat futures under ASC 815 hedge accounting versus mark-to-market, and model the hedge program P&L impact if wheat falls 20% and olive oil rises another 30% after hedges are placed.","tags":["risk-management","commodity-hedging","treasury","manufacturing"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-56","title":"Enterprise Risk Management Framework — Mid-Market PE Portfolio","prompt":"You are a newly hired CFO at a $320M revenue PE-backed distribution company 18 months from a planned exit. The company has no formal enterprise risk management framework — risks are managed informally at the department level. The PE sponsor has asked you to implement a board-quality ERM framework before the exit process begins. Design the ERM framework from scratch: build a risk register covering 20 key risks organized into 5 categories (Strategic, Financial, Operational, Compliance, and Reputational), for each risk define the likelihood (1–5), impact (1–5), risk owner, and current vs. target control effectiveness, identify the top 5 risks that could most materially impair the exit valuation (customer concentration, key-man dependency on the founder-CEO who holds all enterprise relationships, single-ERP system with no disaster recovery, $28M deferred revenue balance with aggressive recognition policy, and a pending EPA environmental remediation at the Ohio DC), build the risk heat map, design the quarterly risk reporting process for the board, and write the 2-page ERM policy statement the PE sponsor can include in the CIM to demonstrate governance maturity to potential acquirors.","tags":["risk-management","erm","private-equity","governance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-57","title":"Cybersecurity Financial Risk Quantification","prompt":"You are the CFO of a $95M ARR healthcare SaaS company handling PHI for 280 hospital clients. The CISO has requested a $3.4M increase in the cybersecurity budget to implement a zero-trust architecture, endpoint detection and response, and a 24/7 SOC-as-a-Service. The board wants to see a financial risk quantification before approving the budget increase. Build the cyber risk financial model: use the FAIR (Factor Analysis of Information Risk) methodology to estimate annual loss expectancy for the 3 most likely breach scenarios — a ransomware attack encrypting the production database (probability 12% per year, loss range $4M–$18M including downtime, recovery, breach notification, and regulatory fines under HIPAA), a third-party vendor credential compromise leading to PHI exposure (probability 8%, loss range $2M–$9M), and a supply chain software attack (probability 4%, loss range $8M–$35M) — calculate the annualized loss expectancy for each scenario, calculate the return on security investment for the $3.4M budget request by comparing ALE before and after controls, model the cyber insurance coverage gap (current policy: $10M limit with a $500K retention and a 30% co-insurance clause), and write the board memo recommending approval with the risk-adjusted financial case.","tags":["risk-management","cybersecurity","quantification","healthcare"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-58","title":"Commercial Loan Underwriting — Middle Market C&I Credit","prompt":"You are a senior credit analyst at a regional bank underwriting a $15M 5-year term loan and $4M revolving credit facility for a 120-employee HVAC services company with $48M in revenue, $4.8M EBITDA, $6.2M in existing senior debt, and the following financials: gross margin 38%, fixed charge coverage ratio 1.42x, total leverage 1.97x, current ratio 1.3, and DSO of 52 days. The loan proceeds will fund the acquisition of a 3-location competitor for $18M (6x EBITDA). Write the complete credit underwriting memo: start with a borrower overview including industry overview (HVAC services — fragmented, recession-resistant, driven by replacement demand), competitive position, and management depth, build the global cash flow analysis consolidating the borrower and guarantors, calculate pro forma leverage (pro forma EBITDA including $600K of synergies) and FCCR at close and in a downside scenario (15% EBITDA decline), structure the loan with appropriate covenant levels (maximum total leverage 4.0x stepping down to 3.5x in year 2, minimum FCCR of 1.20x, minimum liquidity of $1.5M), identify the top 3 credit risks and mitigants, and write the credit risk rating rationale (on a 1–10 scale where 1 is minimal risk).","tags":["banking","credit-analysis","commercial-lending","underwriting"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"fin-59","title":"Cash Management — Corporate Treasury for a 50-Location Retailer","prompt":"You are the Treasurer at a 50-location specialty apparel retailer with $210M in annual revenue, daily cash receipts of $575K spread across 50 store POS systems and a $38M/year e-commerce channel, and a $20M unsecured revolving credit facility with JPMorgan Chase. The company currently uses basic zero-balance accounts at each store that sweep daily into a concentration account, but the CFO believes the company is leaving $600K+ per year in interest income on the table and carrying excessive operational risk. Design an optimized corporate cash management structure: implement a notional pooling structure (if the bank supports it) versus a physical cash concentration sweep comparing net interest benefit, design the bank account structure (how many accounts, which banks, what types), calculate the optimal investment of the daily cash concentration balance using a tiered approach (same-day operating reserve in the sweep account earning Fed Funds rate, 30-day treasury bills for the 30-day liquidity tranche, 3-month T-bills for the strategic reserve), model the incremental annual interest income at current rates (Fed Funds 5.3%), design the fraud control framework for the store cash handling process, and identify the KPIs for the weekly Treasury dashboard.","tags":["banking","treasury","cash-management","retail"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-60","title":"Working Capital Facility — Asset-Based Lending for a Distributor","prompt":"You are the CFO of a $95M revenue building materials distributor with $18M in accounts receivable (45-day DSO), $22M in inventory (62-day turns), and $4M in accounts payable. The company currently has a $10M unsecured revolving credit facility that is fully drawn and insufficient for a planned 30% growth in Q2 as contractor demand surges. You are negotiating an asset-based lending (ABL) facility with a national bank. Design the ABL facility: calculate the borrowing base using standard advance rates (85% of eligible AR excluding invoices over 90 days, government receivables, and contra-balances; 50% of eligible inventory excluding slow-moving items aged over 180 days), estimate the maximum availability assuming $16.4M of eligible AR and $18.2M of eligible inventory, structure the facility terms (3-year commitment, SOFR+175bps pricing on a usage-based grid, $500K annual unused commitment fee, monthly borrowing base certificate requirement, weekly field exam rights), explain the dominion account control structure and how the bank controls cash collections in an ABL, calculate the all-in cost of the ABL versus a conventional cash-flow revolver, and describe the 4 financial covenants the bank will require and the compliance cushion the company should maintain.","tags":["banking","abl","working-capital","credit-facility"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-61","title":"Consumer Credit Scoring Model — Fintech Lender","prompt":"You are the Head of Credit at a fintech consumer lender offering 12-month personal loans from $2,000 to $15,000 to near-prime borrowers (FICO 580–680) who are underserved by traditional banks. You have 18 months of origination data covering 42,000 loans with a 9.2% annualized net charge-off rate. The risk team wants to build a next-generation credit scoring model that reduces NCO to 7% without materially reducing approval rates. Design the credit model development process: define the dependent variable (90+ day delinquency within 12 months), specify the 15 most predictive alternative data features beyond FICO score (payment history on utilities and rent via Experian Boost, bank account cash flow stability from Plaid, employment stability, debt-to-income from income verification, and time-at-address), select the modeling approach comparing logistic regression (interpretable, fair lending defensible) versus gradient boosting (XGBoost) in terms of predictive lift measured by KS statistic and AUC, explain the fair lending validation process under ECOA/Reg B (disparate impact testing across race, gender, and age proxy variables), design the champion-challenger deployment methodology, and calculate the financial impact of a 200bps NCO improvement on the unit economics of a $200M annual origination volume at a 22% APR.","tags":["banking","credit-scoring","fintech","consumer-lending"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-62","title":"Bank Capital Adequacy — Community Bank Stress Test","prompt":"You are the CFO of a $2.2B community bank preparing the annual capital plan for the board and regulators. The bank currently has CET1 capital of $198M (9.0% CET1 ratio), Tier 1 capital of $218M, and Total Capital of $242M (11.0% Total Capital ratio), which is above all well-capitalized thresholds but the OCC examiner has flagged CRE concentration risk (CRE loans are 380% of Tier 1 capital versus the 300% supervisory guidance threshold). Design the capital adequacy analysis: calculate the risk-weighted assets under the standardized approach for the loan portfolio (100% weight for C&I, 100% for CRE, 50% for residential mortgage, 20% for GNMA securities), stress test the capital ratios under a severe recession scenario — assume 8% of CRE loans (currently $680M) become NPLs with 40% loss severity over 2 years, creating $217M in credit losses before tax — and show the post-stress CET1 ratio, analyze whether the bank needs to issue $50M of subordinated debt (qualifies as Tier 2 capital) to maintain adequate capital buffers, evaluate the trade-off between the $42M planned loan growth in CRE and the increasing regulatory scrutiny, and write the Capital Plan narrative the board will submit to the OCC.","tags":["banking","capital-adequacy","community-bank","stress-testing"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-63","title":"Project Finance — Renewable Energy Debt Structuring","prompt":"You are a project finance director at an infrastructure fund structuring the debt financing for a 150MW solar farm in West Texas with a 25-year fixed-price PPA at $38/MWh with a BBB+ rated utility offtaker, a total project cost of $165M, and estimated annual EBITDA of $18.2M beginning in year 2. The fund's equity contribution is $45M and you are structuring $120M in project finance debt. Design the debt structure: calculate the debt sizing using a target DSCR of 1.40x in a P90 production scenario (P90 generation is 8% below the base case P50 forecast of 312,000 MWh/year), structure a 20-year amortizing term loan with a 6-month construction period drawdown, select the appropriate interest rate hedging (fixed rate at 6.85% via interest rate swap versus floating SOFR+210bps), build the cash flow waterfall (operating costs, debt service, DSRA funded to 6-months of P&I, distributions to equity), calculate the equity IRR at the fund level under P50, P90, and a stress scenario where the utility exercises its $32/MWh floor price buyout option in year 10, and explain the key project finance structural protections — the DSCR covenant, reserve accounts, and step-in rights — that protect senior lenders.","tags":["banking","project-finance","renewable-energy","debt-structuring"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-64","title":"Earnings Call Script — Public SaaS Company Q2 Results","prompt":"You are the CFO of a publicly traded SaaS company (NASDAQ: CLDO) preparing for the Q2 earnings call. Q2 results: revenue $48.2M (+34% YoY, beat consensus by $1.4M), non-GAAP operating income $4.1M (8.5% margin, beat by $0.8M), ARR $195M (+31% YoY), NRR 108% (down from 114% a year ago), and the company is lowering full-year revenue guidance from $195M–$199M to $191M–$195M due to elongated enterprise sales cycles. Write the complete earnings call script: open with the CEO's prepared remarks (500 words maximum, lead with the beat, explain the positive Q2 drivers, address the guidance cut proactively and honestly), write the CFO prepared remarks covering the financial results in detail — show the GAAP to non-GAAP reconciliation table, explain the NRR compression and whether it is structural or cyclical, walk through the guidance revision methodology, and provide the Q3 guide, then write 6 likely analyst questions with full CFO and CEO answers covering: (1) the NRR decline trajectory, (2) pipeline health and enterprise deal slippage, (3) the competitive environment from a named competitor that just cut prices, (4) path to profitability timeline, (5) M&A appetite, and (6) the macro sensitivity of the business. Keep language natural and direct — no corporate clichés.","tags":["financial-communication","earnings-call","investor-relations","public-company"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

  {"id":"fin-65","title":"Annual Report CFO Letter — Narrative for Stakeholders","prompt":"You are the CFO of a $480M revenue specialty chemicals company that had a challenging fiscal year — revenue grew 4% (below the 12% target), EBITDA margins contracted 180bps to 16.2% due to raw material cost inflation, but the company completed a strategic acquisition, reduced net leverage from 3.1x to 2.6x through strong cash generation, and invested $38M in a new production facility that will come online next year. Write the CFO's Letter to Shareholders for the Annual Report: open with a direct and honest summary of fiscal year performance (avoid the pattern of burying bad news — acknowledge the revenue miss and margin compression in the first paragraph), give context for each major variance (raw material inflation, the two end markets where volume softened), explain why the acquisition was made at 8.5x EBITDA and what financial returns are expected over 3 years, describe the $38M capex investment and the production economics improvement expected (350bps gross margin improvement when the facility reaches full utilization in year 2), articulate the capital allocation priorities for next year (debt paydown to 2.0x leverage, $25M of bolt-on M&A capacity, maintaining the $0.60/share quarterly dividend), and close with the financial targets for the coming year with the key assumptions behind them. Write in a tone that is confident, transparent, and substantive — not promotional.","tags":["financial-communication","annual-report","investor-relations","cfo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-66","title":"Investor Presentation — Series B Fundraising Deck Financial Narrative","prompt":"You are the CFO of a $14M ARR vertical SaaS company serving independent pharmacies that is raising a $20M Series B at a $70M pre-money valuation. The business has 88% gross margins, 124% NRR, $480K monthly burn, 29 months of runway, and is growing 85% YoY. Write the financial narrative for the 5 financial slides in the Series B investor presentation: Slide 1 — ARR Growth Story: tell the story of ARR growth from $1.2M to $14M in 30 months with the key inflection points (when you hired the VP Sales, when you cracked the pharmacy distributor channel, when you raised prices 22%), Slide 2 — Unit Economics: present CAC ($18K blended, $12K inbound, $28K outbound), LTV ($182K at current NRR and 3.5% annual churn), payback period (18 months), and explain why NRR will expand to 135%+ as the new billing automation module reaches 60% penetration in the existing base, Slide 3 — Use of Proceeds: allocate the $20M across Sales (45%), R&D (30%), CS (15%), G&A (10%) and tie each bucket to a specific ARR milestone it enables, Slide 4 — Path to Series C: show the 24-month operating plan that takes the company from $14M to $34M ARR with improving unit economics and burn multiple below 1.2x, Slide 5 — Market Opportunity: bottom-up TAM calculation for 21,000 independent pharmacies in the US at a $24K ACV, showing how capturing 25% of the market in 5 years gets the company to $126M ARR. For each slide write the 3-sentence verbal narrative the CEO will use to introduce it.","tags":["financial-communication","fundraising","investor-presentation","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-67","title":"Lender Presentation — Covenant Amendment Request","prompt":"You are the CFO of a $145M revenue specialty distribution company that is about to breach its total leverage covenant (currently 4.3x versus the 4.0x covenant level) due to a one-time $8.2M inventory write-down from discontinued SKUs and $3.1M of acquisition-related costs that were supposed to be excluded from the covenant calculation but were inadvertently included in the compliance certificate. You need to approach your bank group (led by Wells Fargo with 4 participating banks) to request a covenant amendment. Write the lender presentation: open with a clear, factual summary of the covenant breach situation — do not minimize or spin the facts, the lenders have the compliance certificate and they know the numbers, briefly recap the Q3 financial results showing the operational business is performing in line with plan (underlying EBITDA ex-items is $36M, ahead of plan), present the reconciliation showing the $11.3M of add-backs that should be permitted under the credit agreement's consolidated EBITDA definition, model the pro forma leverage ratio at 3.6x if the add-backs are recognized, present the 12-month forward operating plan showing deleveraging to 3.1x by Q4 next year through $22M of free cash flow, propose the amendment terms (update the add-back language, request a 4.5x leverage covenant for Q3/Q4 stepping back to 4.0x by Q1), and address the 3 questions the lead bank will definitely ask about downside scenarios.","tags":["financial-communication","banking","covenant-amendment","debt"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-68","title":"Management Discussion and Analysis — 10-K MD&A","prompt":"You are the VP of Financial Reporting at a mid-cap publicly traded healthcare technology company with $340M in revenue, preparing the MD&A section of the 10-K annual report. Revenue grew 18% YoY, operating income grew 31% as S&M leverage improved, but net income was flat due to a $22M non-cash impairment charge on an acquired technology asset. Write a full draft of the Results of Operations section of the MD&A covering: (1) Revenue — explain the 18% growth by segment (SaaS products grew 28%, professional services grew 2%, legacy perpetual licenses declined 15%), quantify the volume versus pricing components, and explain why you expect the perpetual license decline to continue and the growth rate of SaaS to moderate to 20% as the base grows, (2) Gross Profit — explain the margin expansion from 61% to 64% driven by SaaS mix shift and the $3.8M reduction in data center costs from the AWS migration, (3) Operating Expenses — explain the S&M efficiency improvement (S&M as % of revenue declined from 32% to 28%), the R&D investment increase, and the G&A leverage, (4) Impairment — explain the $22M impairment charge on the Healthbridge technology asset acquired 2 years ago and why it was not considered an earlier triggering event, (5) Liquidity — explain the $48M in operating cash flow, the $85M in cash and $30M revolver availability, and the planned capital allocation for next year. Write in compliance with SEC plain English guidelines — no jargon, active voice, specific numbers.","tags":["financial-communication","10-k","sec-reporting","md&a"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-69","title":"Financial Storytelling — Presenting Bad News to the Board","prompt":"You are the CFO of a PE-backed $88M revenue logistics technology company that needs to present Q3 results to the board that include: revenue 14% below plan ($19.2M vs. $22.4M plan), EBITDA -$2.1M versus a planned -$0.4M, a customer churn event (the largest customer at $4.8M ARR gave notice mid-quarter), and a cash balance of $12.4M versus a planned $16.8M — the company will need to raise additional capital or draw the revolver within 5 months at current burn. Write a complete guide to presenting this bad news effectively: explain the communication structure that delivers maximum credibility — lead with the facts before the spin, segment the bad news into controllable versus uncontrollable factors, present the root cause analysis (was the churn an early warning sign or a one-time event?), design the recovery plan slide showing specific actions (cost reductions of $480K/month beginning November 1, pipeline additions to replace the churned ARR by Q2 next year, two identified bridge financing options) with owners and deadlines for each action, and write the exact opening paragraph the CFO will deliver in the first 2 minutes of the meeting that demonstrates accountability without catastrophizing, controls the narrative, and signals that management has a credible plan. Include the 4 questions the PE board members will ask and the recommended answers.","tags":["financial-communication","board-reporting","private-equity","cfo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-70","title":"Press Release — Quarterly Earnings Financial Results","prompt":"You are the Head of Investor Relations at a $1.1B revenue public infrastructure software company (NYSE: INFX) reporting Q3 results that beat top-line consensus but missed EPS by $0.04 due to a $14M incremental R&D investment the company made opportunistically when a competing team became available. Write the complete quarterly earnings press release: write the headline (must lead with the beat metric — revenue $284M, +22% YoY, ahead of $278M consensus), write the opening paragraph in the AP wire style summarizing the quarter's key achievements in 3 sentences, build the standard condensed financial statements (P&L, balance sheet, cash flow) in the format required by Regulation S-K for press release purposes, write the Selected Metrics section showing ARR, NRR, customer count, and remaining performance obligations, write the Q4 guidance section ($288M–$292M revenue, providing a range rather than a point estimate with the key assumptions stated, and non-GAAP EPS guidance of $0.42–$0.46 excluding stock compensation of $18M and amortization of $6M), write the CFO quote that addresses the EPS miss directly without being defensive, and write the standard forward-looking statements safe harbor language. Format the press release for GlobeNewswire distribution.","tags":["financial-communication","press-release","investor-relations","public-company"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-71","title":"Sell-Side M&A Process Letter — LOI Response","prompt":"You are the CFO of a $62M ARR vertical SaaS company (85% gross margins, 118% NRR, $9.1M EBITDA) that received an unsolicited Letter of Intent from a strategic acquiror offering $310M (5x ARR) in cash with a standard 45-day exclusivity period and a $24M management rollover requirement. The board wants a written analysis before responding. Write the complete board response memo: evaluate the offer price against the 5 most relevant precedent transactions and public company trading multiples in vertical SaaS (include Veeva Systems, Procore Technologies, and niche vertical SaaS acquisitions from 2022–2024), calculate the fully diluted equity value and per-share price at $310M versus at alternative valuations of $370M (6x ARR) and $430M (7x ARR) using the current cap table, analyze the 45-day exclusivity period and whether it is sufficient to run a limited competitive process with 3–4 additional potential buyers, evaluate the $24M management rollover requirement and what it signals about the acquiror's integration plans, recommend whether to (a) accept the offer and enter exclusivity, (b) counter at $385M with a 30-day exclusivity period, or (c) reject and run a formal sell-side process, and write the draft response letter to the acquiror for the board's review.","tags":["financial-communication","m&a","sell-side","valuation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-72","title":"Personal Finance — Emergency Fund and Insurance Gap Analysis","prompt":"You are a fee-only financial planner working with a 36-year-old marketing director earning $118K gross in Chicago (take-home $7,200/month after taxes and 401k contributions), with $8,400 in a savings account, $28K in a 401(k), $14K in credit card debt at 21.99% APR, a 5-year-old car financed at $380/month, and two young children (ages 4 and 2). Monthly fixed expenses are $5,800. The client has no disability insurance, a $250K term life policy (employer-paid, not portable), no umbrella policy, and renter's insurance with a $50K contents limit. Conduct a comprehensive financial safety net analysis: calculate the appropriate emergency fund target (3 months vs. 6 months of expenses given the client's industry stability and dual-income status), create a prioritized plan for building the emergency fund while paying down the credit card debt simultaneously, analyze the disability insurance gap (if the client is disabled, the employer plan covers 60% of salary for 90 days then terminates — calculate the income gap and recommend an individual own-occupation DI policy with specific benefit amount and elimination period), calculate the life insurance need using the DIME method (Debt + Income replacement + Mortgage + Education) and compare to the current $250K coverage, and build a 12-month action plan with specific monthly steps.","tags":["personal-finance","insurance","emergency-fund","financial-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-73","title":"Personal Finance — Stock Options and Equity Planning for a Startup Employee","prompt":"You are a financial advisor working with a 31-year-old software engineer who joined a Series B startup 14 months ago, receiving 80,000 ISOs with a $1.20 strike price (current 409A FMV $4.80/share, Series B preferred price $9.60/share). The options vest over 4 years with a 1-year cliff, so 20,000 options just vested. The employee has $22K in savings, $18K in a 401(k), no debt except a $28K car loan at 5.9%, earns $165K base salary, and lives in California. Build a complete equity planning analysis: explain the difference between ISOs and NSOs and why ISO exercise triggers AMT rather than ordinary income, calculate the AMT exposure if all 20,000 vested ISOs are exercised immediately ($4.80 FMV minus $1.20 strike = $3.60 spread × 20,000 = $72,000 AMT income item; calculate the actual incremental AMT tax given the client's regular tax bracket), model whether a partial exercise (exercising 5,000, 10,000, or all 20,000 options) is optimal given the AMT exposure, cash required ($24,000 for all 20,000), and the illiquidity risk if the startup fails to exit, calculate the long-term capital gain benefit of exercising now and holding 1 year (qualifying disposition), and design a multi-year exercise strategy through the anticipated IPO timeline of 24–36 months.","tags":["personal-finance","stock-options","tax-planning","startup"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-74","title":"Personal Finance — Inheritance Planning and Sudden Wealth","prompt":"You are a CFP and estate planning specialist working with a 44-year-old teacher earning $68K/year who just inherited $580K from a parent — consisting of $210K in a traditional IRA, $180K in a brokerage account with a $95K cost basis, $140K in savings bonds (Series EE), and $50K cash in a bank account. The client has $42K in student loans at 4.5%, $18K in a HELOC at 8.9%, and no other assets besides a $140K equity stake in their primary home. Build a complete inheritance management plan: explain the inherited IRA 10-year rule under the SECURE Act 2.0 and calculate the optimal annual distribution strategy to minimize taxes over 10 years given the client's current and projected income in retirement at 67, explain the stepped-up basis rules for the brokerage account and how to calculate the new cost basis on the inherited shares, explain the tax treatment of the Series EE bonds (client must decide whether to report accumulated interest now or defer until redemption), build a debt payoff prioritization (pay off the 8.9% HELOC immediately from cash, evaluate the student loan payoff), and design a 5-year financial plan that transforms this inheritance into a meaningful improvement in the client's retirement readiness, calculating the projected retirement account balances at age 67 versus the baseline without the inheritance.","tags":["personal-finance","inheritance","estate-planning","tax-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-75","title":"Personal Finance — Small Business Owner Financial Planning","prompt":"You are a CPA and financial planner working with a 47-year-old who owns a profitable landscaping business (S-corp election) generating $380K in gross revenue, $180K in net profit before owner compensation, and paying themselves $85K in W-2 salary with the remaining $95K as S-corp distributions. The client has $95K in a SEP-IRA, $48K in personal savings, $320K in home equity on a $680K home, and $85K in equipment loans at 6.8%. They want to retire at 62. Build a comprehensive financial plan for this small business owner: calculate the maximum solo 401(k) contribution available given the S-corp structure (employee deferral of $23,000 + employer contribution of 25% of W-2 salary = $23,000 + $21,250 = $44,250 total), compare the solo 401k to a SEP-IRA contribution limit ($22,500 at 25% of W-2 salary) and show the annual tax savings from maxing the solo 401k at a 32% marginal rate, model the retirement savings accumulation at age 62 assuming $44K/year contributions and 7% annual growth, address the business succession plan (the business is worth an estimated $420K based on 2.5x EBITDA — should the client sell to an employee, a competitor, or bring in a partner?), and calculate whether the client is on track for their retirement goal of $120K/year in real spending power.","tags":["personal-finance","small-business","retirement","tax-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-76","title":"Personal Finance — Navigating a Job Loss with 3 Months of Expenses","prompt":"You are a financial counselor working with a 39-year-old project manager who was laid off 3 weeks ago with a $28K severance (paid over 4 months), $14,200 in a checking account, $62K in a 401(k) at the former employer, $8,400 in a Roth IRA, a $2,200/month mortgage (refinanced at 3.2%, 22 years remaining), $1,200/month in student loan payments (federal loans — currently on a standard 10-year plan), and monthly living expenses of $5,800 total. The client is in a strong job market and expects to find work within 3–4 months. Build a financial triage and recovery plan: calculate the true monthly burn rate during unemployment (net of the $7,000/month severance payments and expected $2,400/month in unemployment benefits), determine exactly how many months of cushion the client has before depleting liquid assets, advise on whether to pause or reduce the student loan payments using the administrative forbearance option under the SAVE plan without penalty, evaluate whether a 401(k) loan from the former employer's plan is advisable (maximum $31K available at prime rate, repayable over 5 years) versus drawing on the Roth IRA contributions (not earnings) penalty-free, design a strict 90-day austerity budget identifying the $1,400 in discretionary spending that can be eliminated, and outline the first 5 financial steps to take in the first week of unemployment.","tags":["personal-finance","job-loss","budgeting","financial-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-77","title":"SaaS Financial Model — [Paste your financial statements or key figures]","prompt":"You are a senior FP&A advisor who has built financial models for 30+ SaaS companies ranging from $1M to $100M ARR. A founder or CFO will paste their current financial statements or key operating metrics below. Your task is to review the numbers and produce a structured analysis covering: (1) Revenue Quality Assessment — calculate MoM ARR growth, implied churn rate from the revenue movements, and flag any signs of revenue acceleration or deceleration, (2) Unit Economics Health — calculate CAC payback period, LTV:CAC ratio, and burn multiple (net new ARR / net burn), and benchmark each metric against typical Series A/B/C benchmarks from Bessemer Venture Partners and OpenView, (3) Burn and Runway Analysis — calculate exact runway at current burn and at a 10% and 20% burn reduction, (4) Path to Rule of 40 — show the current Rule of 40 score and the specific improvement in FCF margin or growth required to reach 40, (5) Top 3 Recommendations — identify the highest-ROI financial levers the company should pull in the next 90 days based on the numbers provided. Format the output as a structured memo with each section clearly headed.\n\n[Paste your financial statements or key figures]","tags":["financial-modeling","saas","fp&a","analysis"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-78","title":"Investment Memo Review — [Paste the investment memo or pitch deck]","prompt":"You are a managing partner at a growth equity fund who has evaluated over 400 investment opportunities across SaaS, fintech, and healthcare technology. A founder or investor will paste an investment memo or pitch deck summary below. Your task is to conduct a rigorous red-team review of the investment thesis covering: (1) Market Sizing Critique — is the TAM calculation bottom-up or top-down, and is it credible? Identify the most aggressive assumption in the market size claim, (2) Business Model Stress Test — what are the 3 scenarios that would prevent the company from reaching the projected ARR in 24 months, and how likely is each?, (3) Competitive Moat Assessment — rate the defensibility of the stated competitive advantages (1–5) and identify the most likely new entrant that would threaten the business in 18 months, (4) Financial Assumption Audit — identify the 3 most optimistic assumptions in the financial projections and provide a range of outcomes using conservative alternatives, (5) Term Sheet Considerations — based on the stage and metrics described, suggest a fair pre-money valuation range and the 3 deal terms that are most critical to negotiate, (6) Pass/Invest Recommendation — give a clear recommendation with the 2 conditions that would change your answer.\n\n[Paste the investment memo or pitch deck]","tags":["investment-analysis","due-diligence","venture","equity-research"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-79","title":"Personal Finance Diagnosis — [Describe your financial situation]","prompt":"You are a Certified Financial Planner with 20 years of experience working with clients across all income levels and life stages. A user will describe their financial situation below in their own words. Your task is to produce a structured financial health assessment covering 6 areas: (1) Emergency Fund Status — calculate how many months of expenses the current liquid savings represent and give a specific target for this person's situation, (2) Debt Priority Map — list every debt described, rank them by payoff priority using both the avalanche (highest APR) and snowball (smallest balance) methods, and recommend which approach fits their stated financial psychology, (3) Retirement Readiness — use the Fidelity 10x salary rule and the 4% safe withdrawal rate to calculate whether they are on track, and if not, calculate the monthly savings increase required, (4) Insurance Gaps — identify any missing coverage (life, disability, umbrella) based on the life stage and dependents described, (5) Tax Optimization Opportunities — identify any tax-advantaged accounts (401k, IRA, HSA, 529) they are not maximizing and the approximate annual tax savings of doing so, (6) 90-Day Action Plan — list 5 specific, prioritized actions with deadlines. Ask clarifying questions before responding if key information is missing (income, debt amounts, monthly expenses, family situation).\n\n[Describe your financial situation]","tags":["personal-finance","financial-planning","budgeting","retirement"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-80","title":"Startup Financial Health Check — [Paste your financial statements or key figures]","prompt":"You are a CFO advisor who has been the fractional CFO for 15 early-stage startups and helped 6 of them successfully raise Series A and B rounds. A founder will paste their financial data or operating metrics below. Produce a structured CFO-level financial health check covering: (1) Cash Runway Precision — calculate exact runway in months using the trailing 3-month average burn rate (not the single latest month which can be distorted), flag if there are large upcoming non-recurring payments that will spike burn, (2) Revenue Recognition Red Flags — based on the metrics provided, identify any signs of aggressive revenue recognition (large deferred revenue balances, unusual payment terms, revenue that exceeds billed amounts), (3) COGS and Gross Margin Trend — calculate gross margin trend over the periods provided and identify whether it is improving or compressing as the company scales, benchmark against typical gross margin ranges for the business model, (4) Sales Efficiency — calculate the magic number (net new ARR × 4 / prior quarter S&M spend) and interpret what it says about go-to-market efficiency, (5) Fundraise Readiness Score — score the company 1–10 on readiness to raise the next round based on 8 criteria including ARR growth rate, burn multiple, gross margin, NRR, months of runway, team completeness, data room readiness, and audit status. Provide specific improvements to reach a score of 8+.\n\n[Paste your financial statements or key figures]","tags":["fp&a","startup","fundraising","financial-modeling"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-81","title":"Leveraged Finance — High-Yield Bond Offering","prompt":"You are a director in the leveraged finance group at a bulge bracket investment bank structuring an $800M high-yield bond offering for a PE-backed software company with $420M revenue, $126M EBITDA (30% margin), and $680M in existing term loan debt being partially refinanced. The company is rated B2/B and the HY market is at a 7.8% average yield for B-rated issuers in the technology sector. Structure the bond offering: determine the optimal maturity (7-year versus 8-year), set the coupon at 8.50% based on current market conditions and the credit profile, structure the call schedule (NC3, callable at 104.25 in year 4, 102.125 in year 5, 101 in year 6, par in year 7), define the covenant package including the restricted payments basket, the incurrence covenants (debt incurrence test at 4.5x leverage, fixed charge coverage test at 2.0x), and the carve-outs that PE sponsors will insist on (builder basket, ratio debt basket, EBITDA add-back basket), calculate the pro forma leverage, interest coverage, and free cash flow profile post-offering, build the investor presentation credit summary highlighting the B2 rating rationale, and explain the 3 risk factors the rating agencies identified as the primary constraints on a higher rating.","tags":["banking","leveraged-finance","high-yield","bonds"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-82","title":"Insurance Company Investment Portfolio — ALM Strategy","prompt":"You are the Chief Investment Officer of a $4.2B regional property and casualty insurance company with $1.8B in investment assets, $980M in loss reserves with an average duration of 3.8 years, a combined ratio of 96.5%, and a 4.2% investment yield target needed to achieve a 10% return on equity. The investment portfolio is currently 65% investment-grade bonds, 12% equities, 8% alternative investments, and 15% short-term instruments. Design an asset-liability management strategy for the next 3 years: match the liability duration of 3.8 years with a target asset duration between 3.5–4.5 years using a combination of 5-year A-rated corporate bonds (yield 5.2%), 10-year Agency MBS (yield 5.65%, but with negative convexity risk), and 3-year Treasuries (yield 4.9%), analyze the duration mismatch risk if interest rates rise 200bps (calculate the impact on surplus), evaluate whether to increase the equity allocation from 12% to 18% given the strong underwriting income, design the credit quality constraints (minimum BBB- on individual securities, maximum BBB allocation of 25%), and calculate the projected investment income improvement from the proposed reallocation.","tags":["banking","insurance","asset-liability","investment-management"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-83","title":"Transfer Pricing — Multinational SaaS Tax Strategy","prompt":"You are the VP of Tax at a US-headquartered SaaS company with $180M in global revenue, entities in Ireland (R&D and IP holding, 60 employees), Singapore (APAC sales, 45 employees), Germany (EMEA sales, 80 employees), and the US parent (headquarters, product, and sales leadership, 310 employees). The company is preparing for its first transfer pricing study as it approaches $200M revenue and expects increased IRS scrutiny. Design the transfer pricing methodology: define the intercompany transactions that need to be priced (IP license from US parent to Ireland IP Co, management services from US to all subsidiaries, distribution margins for Germany and Singapore acting as limited risk distributors), select the appropriate OECD transfer pricing method for each transaction (TNMM for the distribution entities, CUT method for the IP license), calculate the arm's-length royalty rate for the IP license using 10 comparable uncontrolled transactions from the ktMINE database (estimated range 15%–22% of net revenues for B2B SaaS IP), estimate the annual tax savings from the IP holding structure in Ireland (12.5% tax rate versus 21% US rate on $40M of IP income), identify the BEPS Pillar Two implications given the company's €28M Irish entity revenue exceeding the €750M threshold — note this is approaching the threshold and explain the timeline, and recommend the documentation package needed to defend the transfer prices in a US tax audit.","tags":["accounting","transfer-pricing","international-tax","saas"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-84","title":"Financial Due Diligence — Target Company Quality of Earnings","prompt":"You are a Quality of Earnings analyst at a Big 4 accounting firm conducting financial due diligence on a $45M EBITDA specialty distribution company being acquired by a PE firm for $315M (7x EBITDA). The seller provided 3 years of audited financials and a management-prepared EBITDA bridge showing $38M reported EBITDA adjusted to $45M through $7M of add-backs. Conduct a Quality of Earnings analysis: review each of the 7 add-backs ($2.8M owner compensation in excess of market rate, $1.4M one-time legal settlement, $1.1M COVID-era CARES Act PPP loan forgiveness income, $800K in non-recurring IT consulting for an ERP migration, $620K in expenses paid by a related party entity, $180K in one-time recruiting costs, and $100K in excess personal expenses run through the company) and assess whether each is a legitimate add-back under PE industry standards, identify 3 potential negative QoE adjustments the buyer's team missed in the initial review (revenue pulled forward through channel stuffing in Q4, an underaccrual of warranty reserves, and a favorable change in accounting estimate for bad debt), calculate the adjusted QoE EBITDA and the impact on the purchase price at 7x, and write the executive summary page of the QoE report that the PE firm's investment committee will read.","tags":["accounting","quality-of-earnings","due-diligence","private-equity"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-85","title":"SOX Compliance Program — Pre-IPO Internal Controls","prompt":"You are the VP Controller at a SaaS company 12 months from an expected IPO that will make the company subject to Sarbanes-Oxley Section 404(a) (management assessment of internal controls) and eventually 404(b) (auditor attestation when it exceeds $700M market cap). The company has 220 employees, uses NetSuite as the ERP, has never undergone an internal controls assessment, and has a 3-person accounting team. Design the SOX compliance program: start with a scoping exercise to identify the 25 most significant accounts and processes (typically revenue, AR, deferred revenue, equity compensation, and payroll for a SaaS company of this size), map the key controls for each in-scope process using the COSO 2013 internal controls framework (distinguish entity-level controls from process-level controls), identify the 12 IT general controls covering logical access, change management, and backup/recovery that must be tested, design the testing plan for the 6 months leading to IPO (walkthroughs in months 1–2, design effectiveness testing in months 3–4, operating effectiveness testing in months 5–6), estimate the cost of the SOX program in year 1 ($180K–$250K in internal resources, $120K–$180K for an external IT audit firm), and identify the 3 most common first-year SOX deficiencies at companies of this size and how to remediate them before the auditors begin testing.","tags":["accounting","sox","internal-controls","ipo"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-86","title":"Crypto Treasury Policy — Corporate Bitcoin Holdings","prompt":"You are the CFO of a $280M revenue publicly traded payments technology company whose board is debating whether to allocate 5% of the corporate treasury ($18M) into Bitcoin as a long-term store of value, following the precedents set by MicroStrategy and Tesla. You must present a balanced analysis to the board. Write the complete treasury policy analysis: evaluate the strategic rationale (inflation hedge, balance sheet diversification, brand alignment with payment innovation) against the financial risks (BTC price volatility — Bitcoin has experienced 5 drawdowns of 50%+ since 2011, the unrealized loss would appear on the income statement under ASC 350 fair value accounting), explain the accounting treatment under the new FASB ASU 2023-08 which now requires companies to mark crypto assets to fair value with gains and losses through the income statement (a major change from the previous impairment-only model), analyze the tax treatment of corporate Bitcoin purchases and sales under IRS Notice 2014-21, assess the impact on the company's debt covenants (if any covenant restricts speculative investments), model the earnings volatility impact if BTC falls 40% in a single quarter, design a governance framework if the board approves the allocation (cold storage custody policy, approval thresholds for purchases/sales, quarterly reporting to the audit committee), and give a clear CFO recommendation.","tags":["accounting","treasury","crypto","corporate-finance"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-87","title":"Equity Research — Semiconductor Sector Deep Dive","prompt":"You are an equity research analyst at a top-tier asset management firm publishing a sector deep dive on fabless semiconductor companies. Your coverage universe includes Nvidia, AMD, Qualcomm, Marvell Technology, and Monolithic Power Systems. The sector has experienced a sharp correction — the Philadelphia Semiconductor Index is down 28% from its peak — driven by inventory correction in consumer electronics and data center capex uncertainty. Write a sector research piece: open with a 200-word sector thesis explaining whether this is a cyclical correction or a structural inflection point, build a sector model showing each company's current valuation on EV/NTM Revenue, EV/NTM EBITDA, and P/NTM EPS, with premium/discount to historical average multiples, identify the 3 leading indicators you watch to call the bottom of a semiconductor cycle (book-to-bill ratio, channel inventory weeks, lead times at TSMC), compare Nvidia's AI/data center moat to AMD's challenger positioning in the GPU compute market and quantify the addressable GPU AI training market at $130B by 2027, select your highest-conviction long (Nvidia at 28x NTM EPS) and highest-conviction short or underperform (name a specific company and thesis), and write the risk section explaining what would make you wrong on both calls.","tags":["investment-analysis","equity-research","semiconductors","sector"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-88","title":"Private Credit Analysis — Direct Lending Underwrite","prompt":"You are a senior underwriter at a $6B private credit fund evaluating a $45M first lien term loan to provide growth capital to a 180-person healthcare revenue cycle management software company with $38M ARR growing 42% YoY, 82% gross margins, $4.2M EBITDA (trailing), and $8.1M EBITDA (forward, based on management's plan). The sponsor is a lower-middle-market PE firm with a strong track record in healthcare IT. The loan will be priced at SOFR+600bps with a 1% OID, 5-year maturity, and a leverage covenant of 5.5x total debt/EBITDA. Write the credit underwriting analysis: build the leverage and coverage analysis using both trailing and forward EBITDA with a 20% haircut to forward projections for conservatism, calculate the total leverage at close (45/4.2 = 10.7x trailing, but 45/6.5 = 6.9x forward haircut EBITDA — flag this as elevated and explain the documentation mitigants), assess the credit using the 5Cs framework (Character, Capacity, Capital, Collateral, Conditions) with healthcare IT specific considerations (customer concentration, contract durability, reimbursement policy risk), calculate the all-in yield to the fund including OID amortization and upfront fees ($900K arrangement fee), stress test the coverage in a scenario where ARR growth slows to 15% and EBITDA falls 25% from forward plan, and make a credit recommendation with the key conditions precedent to funding.","tags":["banking","private-credit","direct-lending","healthcare"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-89","title":"Municipal Finance — General Obligation Bond Issuance","prompt":"You are the Finance Director of a mid-size city (population 85,000, operating budget $142M) in the Midwest that needs to issue $38M in General Obligation bonds to fund a new public safety complex and fire station renovations. The city's current GO debt outstanding is $94M at an average interest rate of 3.8%, with a Aa3/AA- credit rating from Moody's and S&P based on strong tax base, moderate pension liability, and above-average reserves (18% of operating budget). Design the bond issuance: determine the optimal structure (20-year level debt service versus 25-year with back-loaded amortization to reduce near-term budget impact), calculate the estimated true interest cost at current market rates for Aa3/AA- rated GO bonds (approximately 4.15% TIC for 20-year bonds), build the debt service schedule showing annual principal and interest payments and the impact on the debt service levy, prepare the preliminary official statement summary covering the security pledge (full faith and credit), the tax base ($3.8B equalized assessed value, 97.4% collection rate), key financial metrics (direct debt per capita $1,459, debt as % of EAV 3.5%), and pension liability summary ($68M net pension liability, 72% funded), explain the competitive versus negotiated sale decision and which would likely result in better pricing for this credit, and identify the 4 questions rating agency analysts will focus on most in the surveillance review.","tags":["banking","municipal-finance","bonds","government"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-90","title":"Wealth Management — Ultra-High-Net-Worth Estate Plan","prompt":"You are a private wealth advisor at a bulge bracket bank working with a 68-year-old co-founder of a PE-backed company who recently received $22M in liquidity from a secondary sale. Total net worth is approximately $48M including: $22M cash (post-secondary proceeds), $14M in the remaining illiquid equity stake in the company (expected exit in 2–3 years), $6M in a taxable brokerage account (heavily concentrated in the company's industry), $3.2M in a traditional IRA, $1.8M in a Roth IRA, and $1.2M primary residence (no mortgage). The client is married, has two adult children, and three grandchildren. Design the comprehensive estate and wealth plan: calculate the current federal estate tax exposure at the 2024 $13.61M exemption (the exemption sunsets to approximately $7M per individual in 2026 — calculate the exposure both ways), design a gifting strategy to transfer wealth to the next generation using the annual exclusion ($18K per recipient), evaluate whether a Spousal Lifetime Access Trust (SLAT) is appropriate given the sunset risk, analyze the Grantor Retained Annuity Trust (GRAT) strategy for the remaining illiquid equity position, design the investment allocation for the $22M cash across taxable and tax-advantaged accounts with specific asset location strategy (put REITs and bonds in the IRA, growth equities in the taxable account), and calculate the Roth conversion opportunity in years when the client's income is lower.","tags":["personal-finance","wealth-management","estate-planning","tax-planning"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-91","title":"Financial Model Audit — [Paste your financial statements or key figures]","prompt":"You are a financial model audit specialist who has reviewed hundreds of Excel and Google Sheets financial models built by founders, CFOs, and investment bankers. A user will paste their financial model data or key output tables below. Your task is to conduct a structured model integrity review covering: (1) Logic Checks — identify any circular references, hardcoded values in formula cells, or inconsistent time period assumptions, (2) Balance Sheet Proof — verify the accounting equation balances (Assets = Liabilities + Equity) in each period and flag if retained earnings is not rolling correctly from the P&L, (3) Cash Flow Reconciliation — verify that the indirect method cash flow statement ties back to the balance sheet changes and that capex flows correctly to PP&E, (4) Assumption Transparency — assess whether all key assumptions are clearly isolated in a dedicated inputs section or are buried in formulas, (5) Scenario Architecture — evaluate whether the scenario toggles are correctly wired throughout the model or whether some cells are hardcoded and not sensitivity-tested, (6) Presentation Quality — rate the model's presentation quality (axis labels, number formatting, color coding for inputs vs. calculations) on a 1–10 scale. Provide a prioritized list of fixes with estimated time to correct each issue.\n\n[Paste your financial statements or key figures]","tags":["financial-modeling","model-audit","fp&a","excel"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-92","title":"Subscription Business Financial Benchmarking","prompt":"You are a senior FP&A consultant who specializes in benchmarking subscription and SaaS businesses against industry databases from OpenView Partners, Bessemer Venture Partners, and KeyBanc Capital Markets. You are working with the CFO of a 5-year-old $28M ARR field service management SaaS company growing 55% YoY with 74% gross margins, 105% NRR, $680K monthly burn ($2.88 burn multiple), CAC payback of 22 months, and a 35/65 land/expand revenue split (35% from new logos, 65% from expansion). Conduct a comprehensive benchmarking analysis: benchmark each metric against the median and top quartile for SaaS companies at the $20M–$50M ARR stage using the most recent OpenView SaaS Benchmarks report and KeyBanc Private SaaS Survey data, identify the 3 metrics where the company is below median (likely gross margins at 74% versus 78% median, NRR at 105% versus 115% top quartile, and burn multiple at 2.88 versus 1.5 top quartile), identify the 1 metric where the company is top decile (55% growth is above the 75th percentile at this ARR stage), calculate what improvement in each below-median metric would do to the Series B valuation multiple (every 5 NRR percentage points typically adds 0.5–1.0x ARR multiple at fundraise), and build a 6-month improvement roadmap for the highest-value metric to improve.","tags":["fp&a","benchmarking","saas","metrics"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-93","title":"Tax Planning — R&D Tax Credit Optimization","prompt":"You are a tax director at a $95M revenue software company with an engineering team of 145 people, $28M in annual R&D spend (salaries, contractor costs, cloud compute, and tooling), and an effective tax rate of 24%. The company has claimed the Section 41 R&D tax credit for 3 years but the CFO believes the company is leaving significant credits on the table due to conservative credit identification. Conduct an R&D tax credit optimization analysis: explain the 4-part test for qualifying research activity (section 174 activity, technological nature, uncertainty, process of experimentation) and how it applies specifically to software development activities, identify the 8 qualifying activity categories your engineering teams likely perform that are commonly under-claimed (including new algorithm development, cloud infrastructure optimization, API development, and ML model training), calculate the Qualified Research Expenditure (QRE) base under both the Regular Credit method (20% × QREs in excess of base amount) and the Alternative Simplified Credit (14% × excess of 50% of average QREs for prior 3 years), calculate the estimated additional annual federal R&D credit if QREs increase from the currently claimed $12M to a properly documented $22M, explain the Section 174 amortization requirement that took effect in 2022 and its cash tax impact at your revenue level, and design the documentation system (time tracking, project coding in Jira) needed to defend the expanded credit in an IRS audit.","tags":["accounting","tax-planning","r&d-credits","software"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-94","title":"Financial Reporting — Segment Disclosure for a Diversified Tech Company","prompt":"You are the VP of Financial Reporting at a $1.4B revenue diversified technology company with 3 operating segments: Enterprise Software ($680M revenue, $204M operating income), IT Services ($520M revenue, $52M operating income), and Emerging Technology ($200M revenue, -$38M operating income). The audit committee has asked for a review of segment reporting compliance ahead of the 10-K filing. Conduct the ASC 280 segment reporting analysis: apply the quantitative thresholds to confirm all 3 segments meet the 10% tests (revenue, profit, and assets), analyze the aggregation criteria to determine whether the Enterprise Software and IT Services segments could be aggregated (they share similar economic characteristics and customer types), evaluate whether the Emerging Technology segment's persistent losses require additional disclosure, write the segment footnote for the 10-K including the basis of presentation, the accounting policies for intersegment pricing (cost-plus 8% on shared services), and the reconciliation from segment operating income to consolidated net income, identify the 4 items that most commonly attract SEC comment letters in segment reporting (overly aggregated segments, inconsistency between segment reporting and MD&A, changes in segment definitions, and CEO operating metric disclosures that imply different segment structures), and recommend whether the company should voluntarily provide additional disaggregated revenue disclosures under ASC 606-10-50-5 to improve investor understanding.","tags":["accounting","segment-reporting","sec-reporting","financial-reporting"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-95","title":"Fintech Lending — BNPL Unit Economics and Credit Model","prompt":"You are the Chief Credit Officer at a Buy Now Pay Later fintech company processing $1.2B in annual GMV across 4.2M transactions, with an average order value of $285, a 0-0-4 product (pay in 4 installments, 0% APR to the consumer, 5.8% merchant discount rate), a 3.4% net charge-off rate, and a 12% monthly active user rate among registered users. The CFO wants a complete unit economics model to present to the Series C investors. Build the BNPL unit economics model: calculate gross profit per transaction (merchant fee revenue of $16.53 minus cost of funds for the 6-week float at 6.5% annualized minus net credit losses of 3.4% of GMV minus payment processing costs of 0.85% of GMV), calculate contribution margin after variable customer acquisition cost ($12 blended across paid social, referrals, and merchant-embedded), model the payback period on CAC assuming 4.2 transactions per active user per year, design the credit risk model showing the 5 behavioral features most predictive of BNPL default (number of open BNPL accounts, utilization rate, days since last late payment, frequency of declined transactions, and device fingerprint risk score), calculate the impact on unit economics of tightening credit by 15% (reducing approvals but cutting NCO from 3.4% to 2.6%), and project the path to profitability at $3B GMV scale assuming S&M efficiency improves and fixed cost leverage takes hold.","tags":["fintech","credit-analysis","unit-economics","bnpl"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-96","title":"ESG Reporting — TCFD Climate Risk Financial Disclosure","prompt":"You are the CFO of a $1.8B revenue global food and beverage manufacturer preparing your first Task Force on Climate-related Financial Disclosures (TCFD) report. The company has operations in 12 countries, significant agricultural supply chain exposure, and a stated goal of net-zero emissions by 2040. Write the TCFD financial disclosure framework: under Governance, describe the board oversight structure for climate risk (audit committee reviews climate risk quarterly, sustainability committee has board representation) and management's role (Chief Sustainability Officer reports to CFO); under Strategy, identify the 3 physical risks most material to the business (drought-driven agricultural input cost inflation, flooding risk at the 4 manufacturing plants in coastal Southeast Asia, and heat stress reducing crop yields in key sourcing regions) and the 2 transition risks (carbon pricing mechanisms in the EU and California affecting manufacturing costs, consumer preference shift away from carbon-intensive products), model the financial impact under a 1.5°C scenario and a 3°C scenario through 2030 (estimate the P&L impact in dollar terms), under Risk Management describe how climate risks are integrated into the ERM framework and the annual capital allocation process, under Metrics and Targets disclose the Scope 1, 2, and 3 GHG emissions, the carbon intensity reduction target, and the $85M in green capex planned for the next 3 years.","tags":["accounting","esg","tcfd","climate-risk"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-97","title":"PE Exit Analysis — Strategic vs Sponsor-to-Sponsor vs IPO","prompt":"You are the CFO of a PE-backed vertical SaaS company that your sponsor acquired 4 years ago for $95M. The company has grown from $12M to $58M ARR, expanded EBITDA margins from 8% to 26%, and the current enterprise value is estimated at $380M–$420M based on recent comparable transactions. The sponsor's fund is in year 7 of a 10-year fund life and is beginning to explore exit options. Build the exit alternatives analysis: model the strategic sale scenario — identify the 5 most likely strategic buyers (larger vertical SaaS players, private equity sponsors building a platform, and public cloud companies seeking vertical market entry), estimate the strategic buyer valuation premium (typically 20%–35% above financial buyer pricing due to synergies) and calculate the implied valuation at a 6.5x, 7.0x, and 7.5x ARR multiple, model the sponsor-to-sponsor sale scenario with a $420M LP price — show the sponsor's fund return (invested $52M in equity, plus two follow-on rounds totaling $18M) including DPI and MOIC, model the IPO scenario showing the S-1 filing timeline (18–24 months to be IPO-ready), implied public market valuation at 9x and 11x forward NTM ARR, lockup expiration liquidity, and the ongoing public company compliance cost of $3.5M/year, and recommend the exit path that maximizes risk-adjusted LP returns given the fund lifecycle timing, current M&A market conditions, and the SaaS public market environment.","tags":["corporate-finance","private-equity","exit-analysis","m&a"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-98","title":"CFO Decision Framework — Build vs Buy vs Partner","prompt":"You are the CFO of a $110M ARR SaaS company that needs to add an AI-powered analytics module to the product to remain competitive. The product team has estimated internal build cost at $4.2M over 18 months (8 engineers fully dedicated), the M&A team has identified a potential acquisition target with $8M ARR and $6.2M in technology at an asking price of $38M (a 4.75x ARR multiple with $22M attributed to the technology IP), and a potential OEM partnership with a market-leading analytics vendor at a 28% revenue share on analytics modules sold to existing and new customers. Build a rigorous build vs. buy vs. partner financial analysis: model the 5-year NPV of each option using a 12% discount rate (build: $4.2M upfront then $800K/year maintenance, revenue uplift of $6M ARR in year 2 growing at 40%/year; acquire: $38M outright, $12M integration cost, $20M ARR in year 3 including targets' ARR growing at 35%; partner: $0 upfront, 28% revenue share on $22M of analytics ARR by year 3 growing at 50%), calculate the dilution impact of funding the $38M acquisition via a new equity round at the current $440M valuation versus using the $55M in cash on the balance sheet, identify the 5 non-financial factors that most often determine the real outcome of these decisions (time-to-market, talent retention, customer perception, competitive defensibility, and integration risk), and write a one-page CFO recommendation memo to the CEO and board.","tags":["corporate-finance","build-buy-partner","m&a","strategy"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-99","title":"Fintech Regulation — PSD2 Open Banking Business Model","prompt":"You are the Chief Financial Officer and co-founder of a UK-based open banking fintech startup that uses PSD2 API access to aggregate financial data for 340,000 consumers and monetizes through a B2B2C model — selling the aggregation and analytics API to 28 financial services clients at £85K ACV, generating £2.38M ARR. The business is growing 95% YoY but the CFO of a Series A investor has asked for a detailed analysis of the regulatory and financial risks of the PSD2-dependent business model. Write the regulatory and business model risk analysis: explain the PSD2 AISP (Account Information Service Provider) and PISP (Payment Initiation Service Provider) license requirements and the cost of maintaining FCA authorization (£45K annual FCA fee, £280K annual compliance overhead), analyze the regulatory risk that the UK diverges from EU PSD2 post-Brexit and creates additional compliance costs, model the API rate-limiting risk from major UK banks (Lloyds, Barclays, NatWest have discretion to rate-limit third-party API calls) and the revenue impact if connectivity degrades by 20% during a high-traffic event, analyze the competitive risk from the banks building their own aggregation products (NatWest's Mettle, Lloyds' Bank Smart Business), model the path to £10M ARR showing the revenue per API call pricing model as an alternative to ACV contracts for smaller clients, and design the financial metrics the Series A investor will track to assess whether the regulatory moat is widening or narrowing.","tags":["fintech","open-banking","regulation","uk"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":false},

  {"id":"fin-100","title":"Complete Financial Teardown — [Paste your financial statements or key figures]","prompt":"You are a senior financial advisor with experience across investment banking, private equity, and venture capital who has analyzed thousands of companies across every stage and industry. A user will paste their complete financial statements or a summary of their company's key financial figures below. Your task is to conduct a comprehensive financial teardown covering every dimension of the business's financial health: (1) P&L Quality — is revenue growing, what is the gross margin trend, are operating expenses scaling appropriately relative to revenue, and what does the path to profitability look like?, (2) Balance Sheet Strength — calculate the current ratio, quick ratio, debt/equity, and net cash position; assess whether the balance sheet can support the growth plan, (3) Cash Flow Dynamics — is the business cash flow positive from operations, what is the free cash flow conversion rate from EBITDA, and what is consuming cash?, (4) Capital Efficiency — calculate return on invested capital (ROIC), asset turnover, and revenue per employee; how efficiently is the company converting capital into revenue?, (5) Valuation Context — apply 3 valuation methodologies appropriate for the company's stage and profitability level and provide a valuation range, (6) Peer Benchmarking — benchmark the 5 most important metrics against industry peers if the industry can be inferred, (7) Top 5 Risks — identify the 5 most material financial risks facing the business, (8) Strategic Recommendations — provide 3 specific, actionable financial recommendations ranked by impact. If key information is missing, ask targeted clarifying questions before proceeding.\n\n[Paste your financial statements or key figures]","tags":["financial-modeling","fp&a","analysis","valuation"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true}
];
  __exports.financePrompts = financePrompts;
})();